Use a stack: push opening brackets, and for each closing bracket check the stack top matches the corresponding opening bracket and pop it; reject on mismatch or if the stack is empty, and accept only if the stack is empty at the end.

```typescript
function isValid(s: string): boolean {
  const pairs: Record<string, string> = { ')': '(', '}': '{', ']': '[' };
  const stack: string[] = [];

  for (const ch of s) {
    if (ch === '(' || ch === '{' || ch === '[') {
      stack.push(ch);
    } else {
      if (stack.length === 0 || stack[stack.length - 1] !== pairs[ch]) {
        return false;
      }
      stack.pop();
    }
  }

  return stack.length === 0;
}

// Example usage:
// console.log(isValid("([])")); // true
```

Maintain a running prefix sum and a hashmap of prefix-sum frequencies; for each prefix sum S, add freq[S - k] to the answer and then increment freq[S].

```typescript
function subarraySum(nums: number[], k: number): number {
  const freq = new Map<number, number>();
  // prefix sum 0 occurs once before we start
  freq.set(0, 1);

  let sum = 0;
  let count = 0;

  for (const num of nums) {
    sum += num;
    const need = sum - k;
    if (freq.has(need)) {
      count += freq.get(need)!;
    }
    freq.set(sum, (freq.get(sum) ?? 0) + 1);
  }

  return count;
}

// Example
// console.log(subarraySum([1,1,1], 2)); // 2
```

Do a single pass keeping track of the minimum price seen so far and update the maximum profit as current price minus that minimum.

```typescript
function maxProfit(prices: number[]): number {
  let minPrice = Infinity;
  let maxProfit = 0;

  for (const price of prices) {
    if (price < minPrice) {
      minPrice = price;
    } else {
      const profit = price - minPrice;
      if (profit > maxProfit) maxProfit = profit;
    }
  }

  return maxProfit;
}

// Example
// console.log(maxProfit([7,1,5,3,6,4])); // 5
```

Use a one-pass hash table (map value -> index): for each element, check if its complement (target - nums[i]) is already in the map and return indices if found; otherwise store the current value and index.

```typescript
function twoSum(nums: number[], target: number): number[] {
  const map = new Map<number, number>(); // value -> index
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) {
      return [map.get(complement) as number, i];
    }
    map.set(nums[i], i);
  }
  throw new Error('No two sum solution');
}

// Example:
// console.log(twoSum([2,7,11,15], 9)); // [0, 1]
```

Use two pointers from both ends, maintain leftMax and rightMax, and always advance the side with smaller height while accumulating trapped water based on its max.

```typescript
function trap(height: number[]): number {
  let left = 0;
  let right = height.length - 1;
  let leftMax = 0;
  let rightMax = 0;
  let ans = 0;

  while (left < right) {
    if (height[left] < height[right]) {
      if (height[left] >= leftMax) {
        leftMax = height[left];
      } else {
        ans += leftMax - height[left];
      }
      left++;
    } else {
      if (height[right] >= rightMax) {
        rightMax = height[right];
      } else {
        ans += rightMax - height[right];
      }
      right--;
    }
  }

  return ans;
}

// Example
// console.log(trap([0,1,0,2,1,0,1,3,2,1,2,1])); // 6
```

Use a hash map keyed by a 26-length character-count signature for each string (joined into a string) to group anagrams in O(NK) time.

```typescript
function groupAnagrams(strs: string[]): string[][] {
  const groups = new Map<string, string[]>();

  for (const s of strs) {
    const counts = new Array<number>(26).fill(0);
    for (let i = 0; i < s.length; i++) {
      counts[s.charCodeAt(i) - 97]++;
    }
    const key = counts.join('#');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(s);
  }

  return Array.from(groups.values());
}

// Example usage:
// console.log(groupAnagrams(["eat","tea","tan","ate","nat","bat"]));
```

Use a BFS (level-order) traversal while tracking each node's column index, group values by column in a map, track min/max column to avoid sorting, then emit columns from min to max.

```typescript
interface TreeNode {
  val: number;
  left: TreeNode | null;
  right: TreeNode | null;
}

function verticalOrder(root: TreeNode | null): number[][] {
  if (!root) return [];

  const columnTable = new Map<number, number[]>();
  const queue: Array<[TreeNode, number]> = [];
  let head = 0;

  queue.push([root, 0]);
  let minCol = 0;
  let maxCol = 0;

  while (head < queue.length) {
    const [node, col] = queue[head++];

    if (!columnTable.has(col)) columnTable.set(col, []);
    columnTable.get(col)!.push(node.val);

    if (node.left) {
      queue.push([node.left, col - 1]);
      minCol = Math.min(minCol, col - 1);
    }
    if (node.right) {
      queue.push([node.right, col + 1]);
      maxCol = Math.max(maxCol, col + 1);
    }
  }

  const result: number[][] = [];
  for (let c = minCol; c <= maxCol; c++) {
    result.push(columnTable.get(c) ?? []);
  }
  return result;
}

```

Recursively decompose s into primitive special substrings (mountains), recursively maximize each inner part, sort those parts in descending lexicographic order, and join them.

```typescript
function makeLargestSpecial(s: string): string {
  const parts: string[] = [];
  let i = 0, balance = 0;
  for (let j = 0; j < s.length; j++) {
    if (s[j] === '1') balance++; else balance--;
    if (balance === 0) {
      const inner = makeLargestSpecial(s.slice(i + 1, j));
      parts.push('1' + inner + '0');
      i = j + 1;
    }
  }
  parts.sort((a, b) => b.localeCompare(a));
  return parts.join('');
}

// example
console.log(makeLargestSpecial('11011000')); // '11100100'
```

Use two pointers at the ends and repeatedly move the pointer at the shorter line inward while tracking the maximum area.

```typescript
function maxArea(height: number[]): number {
  let left = 0;
  let right = height.length - 1;
  let max = 0;

  while (left < right) {
    const h = Math.min(height[left], height[right]);
    const width = right - left;
    const area = h * width;
    if (area > max) max = area;

    // Move the pointer at the shorter line inward
    if (height[left] < height[right]) {
      left++;
    } else {
      right--;
    }
  }

  return max;
}

// Example usage:
// console.log(maxArea([1,8,6,2,5,4,8,3,7])); // 49
```

Use horizontal scanning: take the first string as the current prefix and iteratively trim it until it is a prefix of every other string.

```typescript
function longestCommonPrefix(strs: string[]): string {
  if (strs.length === 0) return "";
  let prefix = strs[0];

  for (let i = 1; i < strs.length; i++) {
    // Shorten prefix until strs[i] starts with it
    while (!strs[i].startsWith(prefix)) {
      prefix = prefix.slice(0, -1);
      if (prefix === "") return "";
    }
  }

  return prefix;
}

// Example
console.log(longestCommonPrefix(["flower", "flow", "flight"])); // "fl"
```

Keep an array of elements for O(1) random access and a hashmap from value -> index; for remove, swap the target with the last element and pop, updating the hashmap to maintain O(1) time.

```typescript
class RandomizedSet {
  private idxMap: Map<number, number>;
  private nums: number[];

  constructor() {
    this.idxMap = new Map<number, number>();
    this.nums = [];
  }

  insert(val: number): boolean {
    if (this.idxMap.has(val)) return false;
    this.nums.push(val);
    this.idxMap.set(val, this.nums.length - 1);
    return true;
  }

  remove(val: number): boolean {
    if (!this.idxMap.has(val)) return false;
    const index = this.idxMap.get(val)!;
    const last = this.nums[this.nums.length - 1];

    // Move last element to the place of the element to delete
    this.nums[index] = last;
    this.idxMap.set(last, index);

    // Remove last element
    this.nums.pop();
    this.idxMap.delete(val);
    return true;
  }

  getRandom(): number {
    const i = Math.floor(Math.random() * this.nums.length);
    return this.nums[i];
  }
}

// Example usage:
// const rs = new RandomizedSet();
// rs.insert(1); // true
// rs.remove(2); // false
// rs.insert(2); // true
// rs.getRandom(); // 1 or 2
// rs.remove(1); // true
// rs.insert(2); // false
// rs.getRandom(); // 2
```

Perform a depth-first traversal, passing the current depth and summing integer * depth for each integer encountered.

```typescript
// Type definitions used by LeetCode-style problems
interface NestedInteger {
  // Return true if this NestedInteger holds a single integer, rather than a nested list.
  isInteger(): boolean;
  // Return the single integer that this NestedInteger holds, if it holds a single integer
  // Return null if this NestedInteger holds a nested list
  getInteger(): number | null;
  // Return the nested list that this NestedInteger holds, if it holds a nested list
  // Return null if this NestedInteger holds a single integer
  getList(): NestedInteger[] | null;
}

function depthSum(nestedList: NestedInteger[]): number {
  function dfs(list: NestedInteger[], depth: number): number {
    let sum = 0;
    for (const ni of list) {
      if (ni.isInteger()) {
        const val = ni.getInteger();
        if (val !== null) sum += val * depth;
      } else {
        const inner = ni.getList();
        if (inner !== null) sum += dfs(inner, depth + 1);
      }
    }
    return sum;
  }
  return dfs(nestedList, 1);
}

```

Reverse only the last half of the digits using arithmetic (mod/div by 10) and compare it to the remaining first half.

```typescript
function isPalindrome(x: number): boolean {
  // Negative numbers and numbers ending with 0 (but not 0 itself) cannot be palindromes
  if (x < 0 || (x % 10 === 0 && x !== 0)) return false;

  let reverted = 0;
  let n = x;

  // Build reverted number for the last half of digits
  while (n > reverted) {
    reverted = reverted * 10 + (n % 10);
    n = Math.floor(n / 10);
  }

  // For even length: n === reverted
  // For odd length: n === Math.floor(reverted / 10) (middle digit ignored)
  return n === reverted || n === Math.floor(reverted / 10);
}

// Example usage:
console.log(isPalindrome(121)); // true
console.log(isPalindrome(-121)); // false
console.log(isPalindrome(10)); // false
```

Traverse both lists simultaneously, add corresponding digits plus a carry, create result nodes via a dummy head, and continue until both lists and carry are exhausted.

```typescript
class ListNode {
  val: number;
  next: ListNode | null;
  constructor(val?: number, next?: ListNode | null) {
    this.val = val === undefined ? 0 : val;
    this.next = next === undefined ? null : next;
  }
}

function addTwoNumbers(l1: ListNode | null, l2: ListNode | null): ListNode | null {
  const dummy = new ListNode(0);
  let curr = dummy;
  let carry = 0;

  while (l1 !== null || l2 !== null || carry !== 0) {
    const x = l1 ? l1.val : 0;
    const y = l2 ? l2.val : 0;
    const sum = x + y + carry;
    carry = Math.floor(sum / 10);
    curr.next = new ListNode(sum % 10);
    curr = curr.next;
    if (l1) l1 = l1.next;
    if (l2) l2 = l2.next;
  }

  return dummy.next;
}

```

Use a sliding window with a hash map that stores the last seen index (plus one) of each character; when a repeat is encountered, move the window's left boundary to max(currentLeft, lastSeenIndex) and update the maximum length.

```typescript
function lengthOfLongestSubstring(s: string): number {
  const last = new Map<string, number>(); // stores last seen index + 1
  let left = 0;
  let maxLen = 0;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (last.has(ch)) {
      // move left to the position after the previous occurrence if it's inside the window
      left = Math.max(left, last.get(ch)!);
    }
    // window is [left, i], length = i - left + 1
    maxLen = Math.max(maxLen, i - left + 1);
    // store index + 1 to simplify boundary moves
    last.set(ch, i + 1);
  }

  return maxLen;
}

// Example usage
console.log(lengthOfLongestSubstring("abcabcbb")); // 3
```

Compute the digit-frequency signature of n and check if it matches the signature of any power of two up to 2^29.

```typescript
function reorderedPowerOf2(n: number): boolean {
  const signature = (num: number): string => {
    const cnt = new Array(10).fill(0);
    while (num > 0) {
      cnt[num % 10]++;
      num = Math.floor(num / 10);
    }
    return cnt.join('#');
  };

  const targetSig = signature(n);
  for (let i = 0; i <= 29; i++) {
    const pow = Math.pow(2, i); // 2^0 .. 2^29 cover all powers <= 1e9
    if (signature(pow) === targetSig) return true;
  }
  return false;
}

// Example usage:
// console.log(reorderedPowerOf2(46)); // true
// console.log(reorderedPowerOf2(10)); // false

```

Expand around each center (each index for odd-length and each adjacent pair for even-length) and track the longest palindrome found.

```typescript
function longestPalindrome(s: string): string {
  if (s.length < 2) return s;

  let start = 0;
  let end = 0;

  const expand = (left: number, right: number): number => {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      left--;
      right++;
    }
    // when the while loop breaks, right and left are one step beyond the palindrome
    return right - left - 1;
  };

  for (let i = 0; i < s.length; i++) {
    const len1 = expand(i, i);       // odd-length center
    const len2 = expand(i, i + 1);   // even-length center
    const len = Math.max(len1, len2);

    if (len > end - start + 1) {
      start = i - Math.floor((len - 1) / 2);
      end = i + Math.floor(len / 2);
    }
  }

  return s.slice(start, end + 1);
}

// Example
// console.log(longestPalindrome('babad')) // 'bab' or 'aba'
```

Use two stacks (one for repeat counts and one for accumulated strings) while scanning the input: push state on '[' and pop+repeat on ']' to build the decoded result iteratively.

```typescript
function decodeString(s: string): string {
  const countStack: number[] = [];
  const stringStack: string[] = [];
  let currentNum = 0;
  let currentStr = '';

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch >= '0' && ch <= '9') {
      currentNum = currentNum * 10 + (ch.charCodeAt(0) - 48);
    } else if (ch === '[') {
      countStack.push(currentNum);
      stringStack.push(currentStr);
      currentNum = 0;
      currentStr = '';
    } else if (ch === ']') {
      const k = countStack.pop() ?? 1;
      const prev = stringStack.pop() ?? '';
      currentStr = prev + currentStr.repeat(k);
    } else {
      currentStr += ch;
    }
  }

  return currentStr;
}

// Example
// console.log(decodeString("3[a]2[bc]")); // "aaabcbc"
```

Scan left-to-right with a map from symbol to value: if the next symbol is larger, add (next - current) and skip two chars; otherwise add the current value and advance one.

```typescript
const romanMap: Record<string, number> = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

function romanToInt(s: string): number {
  let i = 0;
  let total = 0;
  while (i < s.length) {
    const curr = romanMap[s[i]];
    const next = i + 1 < s.length ? romanMap[s[i + 1]] : 0;
    if (next > curr) {
      total += next - curr;
      i += 2;
    } else {
      total += curr;
      i += 1;
    }
  }
  return total;
}

// Example
console.log(romanToInt("MCMXCIV")); // 1994
```

Two-pass string-builder: first remove invalid ')' in a left-to-right pass, then remove the required number of '(' (the rightmost ones) in a second pass by keeping only the first needed '(' encountered.

```typescript
function minRemoveToMakeValid(s: string): string {
  // First pass: remove invalid ')' and count '(' occurrences
  const firstPass: string[] = [];
  let balance = 0;      // current open-paren balance
  let openCount = 0;    // number of '(' kept in firstPass

  for (const ch of s) {
    if (ch === '(') {
      balance++;
      openCount++;
      firstPass.push(ch);
    } else if (ch === ')') {
      if (balance > 0) {
        balance--;
        firstPass.push(ch);
      }
      // else skip this unmatched ')'
    } else {
      firstPass.push(ch);
    }
  }

  // balance now equals the number of unmatched '(' to remove
  let keepOpen = openCount - balance; // how many '(' we should keep

  // Second pass: keep only the first keepOpen '(' and all other characters
  const result: string[] = [];
  for (const ch of firstPass) {
    if (ch === '(') {
      if (keepOpen > 0) {
        result.push(ch);
        keepOpen--;
      }
      // else skip this '(' (removing rightmost ones)
    } else {
      result.push(ch);
    }
  }

  return result.join('');
}

// Example
// console.log(minRemoveToMakeValid("lee(t(c)o)de)")); // -> "lee(t(c)o)de"
```

Keep balances in an array and for each operation check index validity and sufficient funds, then update the two affected balances in O(1).

```typescript
class Bank {
  private balances: number[];

  constructor(balance: number[]) {
    // copy to avoid external mutation
    this.balances = balance.slice();
  }

  private valid(account: number): boolean {
    return account >= 1 && account <= this.balances.length;
  }

  transfer(account1: number, account2: number, money: number): boolean {
    if (!this.valid(account1) || !this.valid(account2)) return false;
    const i = account1 - 1;
    const j = account2 - 1;
    if (this.balances[i] < money) return false;
    this.balances[i] -= money;
    this.balances[j] += money;
    return true;
  }

  deposit(account: number, money: number): boolean {
    if (!this.valid(account)) return false;
    this.balances[account - 1] += money;
    return true;
  }

  withdraw(account: number, money: number): boolean {
    if (!this.valid(account)) return false;
    const i = account - 1;
    if (this.balances[i] < money) return false;
    this.balances[i] -= money;
    return true;
  }
}

// Example usage:
// const bank = new Bank([10,100,20,50,30]);
// bank.withdraw(3,10); // true
// bank.transfer(5,1,20); // true
// bank.deposit(5,20); // true
// bank.transfer(3,4,15); // false
// bank.withdraw(10,50); // false
```

Sort intervals by start and scan once, merging a current interval with the last merged interval when they overlap (current.start <= last.end).

```typescript
function merge(intervals: number[][]): number[][] {
  if (intervals.length === 0) return [];

  // Sort by start
  intervals.sort((a, b) => a[0] - b[0]);

  const merged: number[][] = [];
  for (const interval of intervals) {
    if (merged.length === 0) {
      // push a copy to avoid mutating original subarrays
      merged.push([interval[0], interval[1]]);
    } else {
      const last = merged[merged.length - 1];
      if (interval[0] <= last[1]) {
        // overlap -> merge by extending the end
        last[1] = Math.max(last[1], interval[1]);
      } else {
        // no overlap -> append
        merged.push([interval[0], interval[1]]);
      }
    }
  }

  return merged;
}
```

Compute prefix sums of weights, generate a random integer target in [1, totalWeight], and find the smallest prefix >= target by binary search.

```typescript
class Solution {
  private prefix: number[];
  private total: number;

  constructor(w: number[]) {
    this.prefix = new Array(w.length);
    let running = 0;
    for (let i = 0; i < w.length; i++) {
      running += w[i];
      this.prefix[i] = running;
    }
    this.total = running;
  }

  pickIndex(): number {
    // random integer in [1, total]
    const target = Math.floor(Math.random() * this.total) + 1;

    // binary search for first prefix >= target
    let left = 0;
    let right = this.prefix.length - 1;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (this.prefix[mid] < target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  }
}

// Example usage:
// const obj = new Solution([1,3]);
// const idx = obj.pickIndex();

```

Compute the depth of both nodes, lift the deeper node up by the depth difference, then move both nodes up together until they meet at the LCA.

```typescript
class Node {
  val: number;
  left: Node | null;
  right: Node | null;
  parent: Node | null;

  constructor(val?: number, left?: Node | null, right?: Node | null, parent?: Node | null) {
    this.val = val === undefined ? 0 : val;
    this.left = left ?? null;
    this.right = right ?? null;
    this.parent = parent ?? null;
  }
}

function lowestCommonAncestor(p: Node | null, q: Node | null): Node | null {
  if (!p || !q) return null;

  // compute depths
  let depthP = 0;
  let depthQ = 0;
  let a: Node | null = p;
  let b: Node | null = q;
  while (a) { depthP++; a = a.parent; }
  while (b) { depthQ++; b = b.parent; }

  // bring them to the same depth
  while (depthP > depthQ) { p = p!.parent; depthP--; }
  while (depthQ > depthP) { q = q!.parent; depthQ--; }

  // move up together until they meet
  while (p !== q) { p = p!.parent; q = q!.parent; }
  return p;
}

```

