Maintain counts for each row and column plus two counters for the diagonals, adding +1 for player 1 and -1 for player 2 and check if any absolute count reaches n in O(1) per move.

```typescript
class TicTacToe {
  private n: number;
  private rows: number[];
  private cols: number[];
  private diag: number;
  private antiDiag: number;

  constructor(n: number) {
    this.n = n;
    this.rows = new Array(n).fill(0);
    this.cols = new Array(n).fill(0);
    this.diag = 0;
    this.antiDiag = 0;
  }

  move(row: number, col: number, player: number): number {
    const toAdd = player === 1 ? 1 : -1;

    this.rows[row] += toAdd;
    this.cols[col] += toAdd;
    if (row === col) this.diag += toAdd;
    if (col === this.n - row - 1) this.antiDiag += toAdd;

    if (
      Math.abs(this.rows[row]) === this.n ||
      Math.abs(this.cols[col]) === this.n ||
      Math.abs(this.diag) === this.n ||
      Math.abs(this.antiDiag) === this.n
    ) {
      return player;
    }

    return 0;
  }
}

// Example usage:
// const tic = new TicTacToe(3);
// tic.move(0,0,1); // 0
// tic.move(0,2,2); // 0
// ...

```

Maintain for each index the set of distinct OR results of subarrays ending at that index by OR-ing the current value with each value from the previous index's set and accumulate all distinct results in a global set (works in O(n * number_of_bits)).

```typescript
function subarrayBitwiseORs(arr: number[]): number {
  const all = new Set<number>();
  let prev = new Set<number>(); // distinct ORs for subarrays ending at previous index

  for (const num of arr) {
    const cur = new Set<number>();
    cur.add(num);
    for (const v of prev) {
      cur.add(v | num);
    }
    for (const v of cur) all.add(v);
    prev = cur;
  }

  return all.size;
}

// Example
console.log(subarrayBitwiseORs([1,2,4])); // 6
```

Use two pointers to scan abbr and word: when seeing a digit parse the whole number (reject leading zeros) and advance the word pointer by that amount; when seeing a letter, require it to match the current word character.

```typescript
function validWordAbbreviation(word: string, abbr: string): boolean {
  let i = 0; // pointer for word
  let j = 0; // pointer for abbr

  while (j < abbr.length) {
    const ch = abbr[j];
    if (ch >= '0' && ch <= '9') {
      // leading zero not allowed (also disallows a standalone '0')
      if (ch === '0') return false;
      let num = 0;
      while (j < abbr.length && abbr[j] >= '0' && abbr[j] <= '9') {
        num = num * 10 + (abbr.charCodeAt(j) - 48);
        j++;
      }
      i += num;
      if (i > word.length) return false; // jumped past the end
    } else {
      // must match a character
      if (i >= word.length || word[i] !== ch) return false;
      i++;
      j++;
    }
  }

  return i === word.length && j === abbr.length;
}

// Example
// console.log(validWordAbbreviation("internationalization", "i12iz4n")); // true
