Use a doubly linked list to maintain usage order and a hashmap (Map) from key to node so get/put can move nodes and evict the LRU node in O(1).

```typescript
class Node {
  key: number;
  val: number;
  prev: Node | null = null;
  next: Node | null = null;
  constructor(key: number, val: number) { this.key = key; this.val = val; }
}

class LRUCache {
  private capacity: number;
  private map: Map<number, Node>;
  private head: Node; // dummy head
  private tail: Node; // dummy tail
  private size: number = 0;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.map = new Map<number, Node>();
    this.head = new Node(-1, -1);
    this.tail = new Node(-1, -1);
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  private addNode(node: Node): void {
    // insert node before tail (most recently used)
    const prev = this.tail.prev!;
    prev.next = node;
    node.prev = prev;
    node.next = this.tail;
    this.tail.prev = node;
  }

  private removeNode(node: Node): void {
    const prev = node.prev!;
    const next = node.next!;
    prev.next = next;
    next.prev = prev;
    node.prev = node.next = null;
  }

  private moveToTail(node: Node): void {
    this.removeNode(node);
    this.addNode(node);
  }

  private popHead(): Node | null {
    const node = this.head.next;
    if (!node || node === this.tail) return null;
    this.removeNode(node);
    return node;
  }

  get(key: number): number {
    const node = this.map.get(key);
    if (!node) return -1;
    this.moveToTail(node);
    return node.val;
  }

  put(key: number, value: number): void {
    const existing = this.map.get(key);
    if (existing) {
      existing.val = value;
      this.moveToTail(existing);
      return;
    }

    const node = new Node(key, value);
    this.map.set(key, node);
    this.addNode(node);
    this.size++;

    if (this.size > this.capacity) {
      const removed = this.popHead();
      if (removed) {
        this.map.delete(removed.key);
        this.size--;
      }
    }
  }
}

// Example usage (LeetCode-style):
// const cache = new LRUCache(2);
// cache.put(1,1); cache.put(2,2); console.log(cache.get(1)); // 1
// cache.put(3,3); console.log(cache.get(2)); // -1
// cache.put(4,4); console.log(cache.get(1)); // -1
// console.log(cache.get(3)); // 3
// console.log(cache.get(4)); // 4
