Build three hash structures — an exact set, a lowercase->first-original map, and a vowel-masked-lowercase->first-original map — and check each query in that precedence order.

```typescript
function spellchecker(wordlist: string[], queries: string[]): string[] {
  const isVowel = (ch: string) => 'aeiou'.includes(ch);
  const devowel = (word: string) => {
    const a = word.split('');
    for (let i = 0; i < a.length; i++) if (isVowel(a[i])) a[i] = '*';
    return a.join('');
  };

  const exact = new Set<string>(wordlist);
  const lowerMap = new Map<string, string>();
  const vowelMap = new Map<string, string>();

  for (const w of wordlist) {
    const lower = w.toLowerCase();
    if (!lowerMap.has(lower)) lowerMap.set(lower, w);
    const dev = devowel(lower);
    if (!vowelMap.has(dev)) vowelMap.set(dev, w);
  }

  const ans: string[] = [];
  for (const q of queries) {
    if (exact.has(q)) {
      ans.push(q);
      continue;
    }
    const lowerQ = q.toLowerCase();
    if (lowerMap.has(lowerQ)) {
      ans.push(lowerMap.get(lowerQ)!);
      continue;
    }
    const devQ = devowel(lowerQ);
    if (vowelMap.has(devQ)) {
      ans.push(vowelMap.get(devQ)!);
      continue;
    }
    ans.push("");
  }
  return ans;
}

// Example usage:
// const wordlist = ["KiTe","kite","hare","Hare"];
// const queries = ["kite","Kite","KiTe","Hare","HARE","Hear","hear","keti","keet","keto"];
// console.log(spellchecker(wordlist, queries));
```

Sort the array and for each index use the two-pointer technique to find pairs summing to -nums[i], skipping duplicates to avoid repeated triplets.

```typescript
function threeSum(nums: number[]): number[][] {
  const res: number[][] = [];
  nums.sort((a, b) => a - b);
  const n = nums.length;

  for (let i = 0; i < n - 2; i++) {
    if (nums[i] > 0) break; // no possible triplet if smallest is > 0
    if (i > 0 && nums[i] === nums[i - 1]) continue; // skip duplicate pivot

    let lo = i + 1;
    let hi = n - 1;

    while (lo < hi) {
      const sum = nums[i] + nums[lo] + nums[hi];
      if (sum === 0) {
        res.push([nums[i], nums[lo], nums[hi]]);
        lo++;
        hi--;
        // skip duplicates for lo and hi
        while (lo < hi && nums[lo] === nums[lo - 1]) lo++;
        while (lo < hi && nums[hi] === nums[hi + 1]) hi--;
      } else if (sum < 0) {
        lo++;
      } else {
        hi--;
      }
    }
  }

  return res;
}

// Example usage:
// console.log(threeSum([-1,0,1,2,-1,-4])); // [[-1,-1,2],[-1,0,1]]
