Do a binary search on the smaller array to find a partition where max(left halves) <= min(right halves), then compute the median from the partition edge values.

```typescript
function findMedianSortedArrays(nums1: number[], nums2: number[]): number {
  // Ensure nums1 is the smaller array
  if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);

  const m = nums1.length;
  const n = nums2.length;
  let left = 0;
  let right = m;
  const half = Math.floor((m + n + 1) / 2);

  while (left <= right) {
    const i = Math.floor((left + right) / 2); // partition in nums1
    const j = half - i; // partition in nums2

    // If i is too small, must move right (nums1[i] is less than nums2[j-1])
    if (i < m && j > 0 && nums2[j - 1] > nums1[i]) {
      left = i + 1;
    }
    // If i is too big, must move left (nums1[i-1] is greater than nums2[j])
    else if (i > 0 && j < n && nums1[i - 1] > nums2[j]) {
      right = i - 1;
    }
    // i is perfect
    else {
      let maxLeft: number;
      if (i === 0) maxLeft = nums2[j - 1];
      else if (j === 0) maxLeft = nums1[i - 1];
      else maxLeft = Math.max(nums1[i - 1], nums2[j - 1]);

      // If odd total length, median is maxLeft
      if ((m + n) % 2 === 1) return maxLeft;

      let minRight: number;
      if (i === m) minRight = nums2[j];
      else if (j === n) minRight = nums1[i];
      else minRight = Math.min(nums1[i], nums2[j]);

      return (maxLeft + minRight) / 2;
    }
  }

  // Should not reach here if inputs are valid
  return 0;
}

