Perform a flood-fill (DFS) from each unvisited '1', marking visited cells as '0' and counting each DFS start as one island.

```typescript
function numIslands(grid: string[][]): number {
  if (!grid || grid.length === 0) return 0;
  const m = grid.length, n = grid[0].length;
  let count = 0;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === '1') {
        count++;
        const stack: [number, number][] = [[i, j]];
        grid[i][j] = '0';
        while (stack.length) {
          const [r, c] = stack.pop()!;
          for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === '1') {
              stack.push([nr, nc]);
              grid[nr][nc] = '0';
            }
          }
        }
      }
    }
  }

  return count;
}
