Return false if length < 3, then do a single pass checking each character is either a digit or a letter while tracking whether at least one vowel and one consonant appear, rejecting immediately on any invalid character.

```typescript
function validWord(word: string): boolean {
  if (word.length < 3) return false;

  const vowels = new Set(['a','e','i','o','u','A','E','I','O','U']);
  let hasVowel = false;
  let hasConsonant = false;

  for (const ch of word) {
    // digit
    if (ch >= '0' && ch <= '9') continue;

    // letter
    if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
      if (vowels.has(ch)) hasVowel = true;
      else hasConsonant = true;
      continue;
    }

    // any other character is invalid
    return false;
  }

  return hasVowel && hasConsonant;
}

