Use backtracking to build only valid prefixes: add '(' while open < n and add ')' while close < open, collecting completed strings of length 2n.

```typescript
function generateParentheses(n: number): string[] {
  const res: string[] = [];
  const buf: string[] = [];

  function backtrack(open: number, close: number) {
    if (buf.length === 2 * n) {
      res.push(buf.join(''));
      return;
    }

    if (open < n) {
      buf.push('(');
      backtrack(open + 1, close);
      buf.pop();
    }

    if (close < open) {
      buf.push(')');
      backtrack(open, close + 1);
      buf.pop();
    }
  }

  backtrack(0, 0);
  return res;
}

