Build a segment tree that stores the maximum capacity per interval and supports a find-first operation (leftmost index with value >= x) plus point updates to 0, then process fruits left-to-right using that find-first in O(log n) each.

```typescript
class SegmentTree {
  n: number;
  tree: number[];

  constructor(arr: number[]) {
    this.n = arr.length;
    this.tree = new Array(this.n * 4).fill(0);
    this.build(1, 0, this.n - 1, arr);
  }

  private build(node: number, l: number, r: number, arr: number[]) {
    if (l === r) {
      this.tree[node] = arr[l];
      return;
    }
    const mid = (l + r) >> 1;
    this.build(node << 1, l, mid, arr);
    this.build((node << 1) | 1, mid + 1, r, arr);
    this.tree[node] = Math.max(this.tree[node << 1], this.tree[(node << 1) | 1]);
  }

  update(node: number, l: number, r: number, idx: number, val: number) {
    if (l === r) {
      this.tree[node] = val;
      return;
    }
    const mid = (l + r) >> 1;
    if (idx <= mid) this.update(node << 1, l, mid, idx, val);
    else this.update((node << 1) | 1, mid + 1, r, idx, val);
    this.tree[node] = Math.max(this.tree[node << 1], this.tree[(node << 1) | 1]);
  }

  // return leftmost index in [l..r] with value >= x, or -1 if none
  findFirst(node: number, l: number, r: number, x: number): number {
    if (this.tree[node] < x) return -1;
    if (l === r) return l;
    const mid = (l + r) >> 1;
    if (this.tree[node << 1] >= x) return this.findFirst(node << 1, l, mid, x);
    return this.findFirst((node << 1) | 1, mid + 1, r, x);
  }
}

function fruitsIntoBaskets(fruits: number[], baskets: number[]): number {
  const n = baskets.length;
  const seg = new SegmentTree(baskets);
  let unplaced = 0;
  for (const f of fruits) {
    // if overall max < f, cannot place
    if (seg.tree[1] < f) {
      unplaced++;
    } else {
      const idx = seg.findFirst(1, 0, n - 1, f);
      if (idx === -1) unplaced++;
      else seg.update(1, 0, n - 1, idx, 0); // occupy basket
    }
  }
  return unplaced;
}

// Example usage:
// console.log(fruitsIntoBaskets([4,2,5], [3,5,4])); // 1
```

Maintain a deque of (timestamp, count) pairs plus a running total: combine consecutive hits with the same timestamp on hit(), and evict outdated pairs while updating the total on getHits().

```typescript
class HitCounter {
  private queue: { ts: number; count: number }[] = [];
  private total: number = 0;

  constructor() {}

  // Record a hit at 'timestamp'
  hit(timestamp: number): void {
    const n = this.queue.length;
    if (n > 0 && this.queue[n - 1].ts === timestamp) {
      // same timestamp as last entry: increment its count
      this.queue[n - 1].count += 1;
    } else {
      // new timestamp entry
      this.queue.push({ ts: timestamp, count: 1 });
    }
    this.total += 1;
  }

  // Return number of hits in the past 300 seconds from 'timestamp'
  getHits(timestamp: number): number {
    // evict outdated entries
    while (this.queue.length > 0 && timestamp - this.queue[0].ts >= 300) {
      this.total -= this.queue[0].count;
      this.queue.shift();
    }
    return this.total;
  }
}

// Example usage:
// const hc = new HitCounter();
// hc.hit(1); hc.hit(2); hc.hit(3);
// console.log(hc.getHits(4)); // 3
// hc.hit(300);
// console.log(hc.getHits(300)); // 4
// console.log(hc.getHits(301)); // 3
