Compute the multinomial ways to interleave infections across the empty segments and multiply by 2^{g-1} for each internal segment of length g (between two initial sick) to account for extra ordering choices, using factorials and inverse factorials modulo 1e9+7.

```typescript
const MOD = 1000000007n;

function modPow(a: bigint, e: bigint): bigint {
  let res = 1n;
  let base = a % MOD;
  while (e > 0n) {
    if (e & 1n) res = (res * base) % MOD;
    base = (base * base) % MOD;
    e >>= 1n;
  }
  return res;
}

function countInfectionSequences(n: number, sick: number[]): number {
  const k = sick.length;
  const m = n - k; // number of people to become infected
  // precompute factorials and inverse factorials up to n
  const N = n;
  const fact: bigint[] = Array(N + 1).fill(0n);
  const invFact: bigint[] = Array(N + 1).fill(0n);
  fact[0] = 1n;
  for (let i = 1; i <= N; ++i) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
  invFact[N] = modPow(fact[N], MOD - 2n);
  for (let i = N - 1; i >= 0; --i) invFact[i] = (invFact[i + 1] * BigInt(i + 1)) % MOD;

  let res = fact[m];

  // left edge gap
  const left = sick[0] - 0;
  if (left > 0) {
    res = (res * invFact[left]) % MOD;
  }

  // right edge gap
  const right = (n - 1) - sick[sick.length - 1];
  if (right > 0) {
    res = (res * invFact[right]) % MOD;
  }

  // middle gaps
  for (let i = 1; i < sick.length; ++i) {
    const gap = sick[i] - sick[i - 1] - 1; // number of uninfected between two sick
    if (gap === 0) continue;
    // divide by gap! for multinomial
    res = (res * invFact[gap]) % MOD;
    // multiply by 2^{gap-1} for internal segment choices
    if (gap > 0) {
      res = (res * modPow(2n, BigInt(gap - 1))) % MOD;
    }
  }

  return Number(res);
}

// Example usage:
// console.log(countInfectionSequences(5, [0, 4])); // 4

```

Work backwards from (tx, ty) using modulo to batch reverse steps: repeatedly replace the larger coordinate with its remainder mod the smaller until you can directly check reachability to (sx, sy).

```typescript
function reachingPoints(sx: number, sy: number, tx: number, ty: number): boolean {
  // Work backwards from (tx, ty) to (sx, sy)
  while (tx > sx && ty > sy) {
    if (tx > ty) {
      tx %= ty;
    } else {
      ty %= tx;
    }
  }

  if (tx === sx && ty === sy) return true;
  if (tx === sx) {
    // tx fixed, check if we can reduce ty to sy by subtracting multiples of tx
    return ty >= sy && ((ty - sy) % tx === 0);
  }
  if (ty === sy) {
    // ty fixed, check if we can reduce tx to sx by subtracting multiples of ty
    return tx >= sx && ((tx - sx) % ty === 0);
  }
  return false;
}

// Example usage:
console.log(reachingPoints(1, 1, 3, 5)); // true
console.log(reachingPoints(1, 1, 2, 2)); // false
console.log(reachingPoints(1, 1, 1, 1)); // true
