Use a min-heap seeded with all boundary cells and perform a BFS inward: always expand from the lowest boundary cell, trapping water when neighbor height is lower and pushing neighbors with an updated effective height.

```typescript
function trapRainWater(heightMap: number[][]): number {
  const m = heightMap.length;
  if (m === 0) return 0;
  const n = heightMap[0].length;
  if (m <= 2 || n <= 2) return 0; // no room to trap

  type Cell = { h: number; r: number; c: number };

  class MinHeap {
    heap: Cell[] = [];

    size(): number {
      return this.heap.length;
    }

    push(cell: Cell): void {
      this.heap.push(cell);
      this.siftUp(this.heap.length - 1);
    }

    pop(): Cell | undefined {
      if (this.heap.length === 0) return undefined;
      const top = this.heap[0];
      const last = this.heap.pop()!;
      if (this.heap.length > 0) {
        this.heap[0] = last;
        this.siftDown(0);
      }
      return top;
    }

    private siftUp(i: number) {
      while (i > 0) {
        const p = Math.floor((i - 1) / 2);
        if (this.heap[p].h <= this.heap[i].h) break;
        [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
        i = p;
      }
    }

    private siftDown(i: number) {
      const n = this.heap.length;
      while (true) {
        let smallest = i;
        const l = i * 2 + 1;
        const r = i * 2 + 2;
        if (l < n && this.heap[l].h < this.heap[smallest].h) smallest = l;
        if (r < n && this.heap[r].h < this.heap[smallest].h) smallest = r;
        if (smallest === i) break;
        [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
        i = smallest;
      }
    }
  }

  const visited: boolean[][] = Array.from({ length: m }, () => Array(n).fill(false));
  const heap = new MinHeap();

  // Push all boundary cells
  for (let r = 0; r < m; r++) {
    visited[r][0] = true;
    visited[r][n - 1] = true;
    heap.push({ h: heightMap[r][0], r, c: 0 });
    heap.push({ h: heightMap[r][n - 1], r, c: n - 1 });
  }
  for (let c = 1; c < n - 1; c++) {
    visited[0][c] = true;
    visited[m - 1][c] = true;
    heap.push({ h: heightMap[0][c], r: 0, c });
    heap.push({ h: heightMap[m - 1][c], r: m - 1, c });
  }

  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let water = 0;

  while (heap.size() > 0) {
    const cell = heap.pop()!;
    for (const [dr, dc] of dirs) {
      const nr = cell.r + dr;
      const nc = cell.c + dc;
      if (nr < 0 || nr >= m || nc < 0 || nc >= n || visited[nr][nc]) continue;
      visited[nr][nc] = true;
      const nh = heightMap[nr][nc];
      if (nh < cell.h) {
        water += cell.h - nh; // trapped
      }
      // push neighbor with effective height = max(neighborHeight, boundaryHeight)
      heap.push({ h: Math.max(nh, cell.h), r: nr, c: nc });
    }
  }

  return water;
}

// Example usage:
// console.log(trapRainWater([[1,4,3,1,3,2],[3,2,1,3,2,4],[2,3,3,2,3,1]])); // 4

```

Greedily collect as many words as fit per line, then build each line by distributing total extra spaces evenly across the gaps (leftmost gaps get the remainder), with the last line and single-word lines left-justified.

```typescript
function fullJustify(words: string[], maxWidth: number): string[] {
  const res: string[] = [];
  const n = words.length;
  let i = 0;

  while (i < n) {
    // Determine range [i, j) of words that fit on this line
    let sumLen = 0;
    let j = i;
    while (j < n && sumLen + words[j].length + (j - i) <= maxWidth) {
      sumLen += words[j].length;
      j++;
    }

    const lineWords = words.slice(i, j);
    const isLast = j === n;

    if (isLast || lineWords.length === 1) {
      // Left-justify: single spaces between words, pad end
      let line = lineWords.join(' ');
      line += ' '.repeat(maxWidth - line.length);
      res.push(line);
    } else {
      // Fully justify: distribute spaces evenly
      const totalSpaces = maxWidth - sumLen;
      const slots = lineWords.length - 1;
      const spacesPerSlot = Math.floor(totalSpaces / slots);
      let extra = totalSpaces % slots; // leftmost slots get one extra

      let line = '';
      for (let k = 0; k < lineWords.length; k++) {
        line += lineWords[k];
        if (k < lineWords.length - 1) {
          line += ' '.repeat(spacesPerSlot + (extra > 0 ? 1 : 0));
          if (extra > 0) extra--;
        }
      }
      res.push(line);
    }

    i = j;
  }

  return res;
}

```

Do a single pass tracking the length of the current same-character run and the previous run; whenever the character changes add min(prev, cur) to the answer.

```typescript
function countBinarySubstrings(s: string): number {
  let prev = 0;
  let cur = 1;
  let ans = 0;

  for (let i = 1; i < s.length; i++) {
    if (s[i] !== s[i - 1]) {
      ans += Math.min(prev, cur);
      prev = cur;
      cur = 1;
    } else {
      cur++;
    }
  }

  ans += Math.min(prev, cur);
  return ans;
}
