Convert the start IP to a 32-bit integer, repeatedly take the largest power-of-two block aligned at the current start that doesn't exceed the remaining count, emit its CIDR, and advance until all addresses are covered.

```typescript
function ipToBigInt(ip: string): bigint {
  const parts = ip.split('.').map(Number);
  return (BigInt(parts[0]) << 24n) | (BigInt(parts[1]) << 16n) | (BigInt(parts[2]) << 8n) | BigInt(parts[3]);
}

function bigIntToIp(x: bigint): string {
  const a = Number((x >> 24n) & 255n);
  const b = Number((x >> 16n) & 255n);
  const c = Number((x >> 8n) & 255n);
  const d = Number(x & 255n);
  return `${a}.${b}.${c}.${d}`;
}

function lowestPowerOfTwoDividing(x: bigint): bigint {
  // returns x & -x, but handle x == 0
  if (x === 0n) return 1n << 32n; // treat as fully aligned
  return x & (-x);
}

function log2BigintPow2(x: bigint): number {
  // x must be a power of two
  let pos = 0;
  while (x > 1n) {
    x >>= 1n;
    pos++;
  }
  return pos;
}

export function ipToCIDR(ip: string, n: number): string[] {
  let start = ipToBigInt(ip);
  let remain = BigInt(n);
  const ans: string[] = [];

  while (remain > 0n) {
    let maxAlign = lowestPowerOfTwoDividing(start);
    let block = maxAlign;
    // shrink block until it fits in remaining addresses
    while (block > remain) {
      block >>= 1n;
    }
    const bits = log2BigintPow2(block); // block = 2^bits
    const prefix = 32 - bits;
    ans.push(`${bigIntToIp(start)}/${prefix}`);
    start += block;
    remain -= block;
  }

  return ans;
}

// Example usage:
// console.log(ipToCIDR("255.0.0.7", 10));

