Sort meetings by start time, then use a min-heap of current meeting end times to reuse a room when the earliest-ending meeting ends before the next meeting starts; otherwise allocate a new room.

```typescript
class MinHeap {
  private a: number[] = [];
  size(): number { return this.a.length; }
  peek(): number | undefined { return this.a[0]; }

  push(x: number): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }

  pop(): number | undefined {
    const a = this.a;
    if (a.length === 0) return undefined;
    const top = a[0];
    const last = a.pop()!;
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      while (true) {
        const l = i * 2 + 1;
        const r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m], a[i]];
        i = m;
      }
    }
    return top;
  }
}

function minMeetingRooms(intervals: number[][]): number {
  if (intervals.length === 0) return 0;

  intervals.sort((x, y) => x[0] - y[0]);

  const heap = new MinHeap();
  heap.push(intervals[0][1]);

  for (let i = 1; i < intervals.length; i++) {
    const [start, end] = intervals[i];
    const earliestEnd = heap.peek()!;

    if (start >= earliestEnd) {
      heap.pop(); // reuse that room
    }
    heap.push(end); // occupy a room until 'end'
  }

  return heap.size();
}

