Simulate the diagonal walk: visit cells one-by-one, move up-right or down-left depending on current direction, and when hitting a boundary adjust the head (row/col) and toggle direction.

```typescript
function diagonalTraverse(mat: number[][]): number[] {
  if (mat.length === 0) return [];
  const m = mat.length, n = mat[0].length;
  const total = m * n;
  const res: number[] = new Array(total);

  let r = 0, c = 0; // current position
  let dir = 1; // 1 => moving up-right, -1 => moving down-left
  let i = 0; // index in result

  while (i < total) {
    res[i++] = mat[r][c];

    if (dir === 1) {
      // moving up-right
      if (c === n - 1) { // hit right border -> move down
        r++;
        dir = -1;
      } else if (r === 0) { // hit top border -> move right
        c++;
        dir = -1;
      } else { // normal move
        r--;
        c++;
      }
    } else {
      // moving down-left
      if (r === m - 1) { // hit bottom border -> move right
        c++;
        dir = 1;
      } else if (c === 0) { // hit left border -> move down
        r++;
        dir = 1;
      } else { // normal move
        r++;
        c--;
      }
    }
  }

  return res;
}

