Store numbers in a HashSet for O(1) lookups and only attempt to build a sequence from numbers that have no predecessor (num-1 not in the set).

```typescript
function longestConsecutive(nums: number[]): number {
  if (nums.length === 0) return 0;

  const set = new Set<number>(nums);
  let longest = 0;

  for (const num of set) {
    // only start counting at sequence starts
    if (!set.has(num - 1)) {
      let current = num;
      let length = 1;
      while (set.has(current + 1)) {
        current++;
        length++;
      }
      longest = Math.max(longest, length);
    }
  }

  return longest;
}

