Perform BFS from each building, accumulate distances into a total-distance matrix and use the input grid itself as a visitation/reachability marker by decrementing empty-cell values after each BFS so only cells reachable from all buildings remain candidates.

```typescript
function shortestDistance(grid: number[][]): number {
  const m = grid.length;
  const n = grid[0].length;
  const totalDist: number[][] = Array.from({ length: m }, () => Array(n).fill(0));

  // emptyLandValue starts at 0; after each building BFS we decrement it.
  // Cells reachable from k processed buildings will have value = -k.
  let emptyLandValue = 0;

  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        // BFS from building (i, j)
        const queue: number[][] = [];
        let head = 0;
        queue.push([i, j, 0]); // x, y, distance from building

        while (head < queue.length) {
          const [x, y, d] = queue[head++];

          for (const [dx, dy] of dirs) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] === emptyLandValue) {
              // mark visited for this BFS (decrement so it's not visited again in this BFS)
              grid[nx][ny] = emptyLandValue - 1;
              totalDist[nx][ny] += d + 1;
              queue.push([nx, ny, d + 1]);
            }
          }
        }

        // After finishing this building, require next BFS to only visit the cells visited by all previous buildings
        emptyLandValue--;
      }
    }
  }

  // After all building BFSs, cells reachable from all buildings have value == emptyLandValue
  let ans = Infinity;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === emptyLandValue) {
        ans = Math.min(ans, totalDist[i][j]);
      }
    }
  }

  return ans === Infinity ? -1 : ans;
}

```

Iteratively pop digits from x and push them into a result while checking before each push whether the next multiply/add would overflow the 32-bit signed range.

```typescript
function reverse(x: number): number {
  const INT_MAX = 2 ** 31 - 1;
  const INT_MIN = -(2 ** 31);
  let rev = 0;

  while (x !== 0) {
    const pop = x % 10;
    x = Math.trunc(x / 10);

    // Check overflow for positive side
    if (rev > INT_MAX / 10 || (rev === Math.trunc(INT_MAX / 10) && pop > 7)) {
      return 0;
    }
    // Check overflow for negative side
    if (rev < INT_MIN / 10 || (rev === Math.trunc(INT_MIN / 10) && pop < -8)) {
      return 0;
    }

    rev = rev * 10 + pop;
  }

  return rev;
}

// Examples
console.log(reverse(123)); // 321
console.log(reverse(-123)); // -321
console.log(reverse(120)); // 21
