Repeat marking crushable candies in-place by negating their absolute values, set marked cells to 0, apply gravity per column, and loop until no marks are found.

```typescript
function candyCrush(board: number[][]): number[][] {
  const m = board.length;
  const n = board[0].length;

  while (true) {
    let crushed = false;

    // mark horizontal triples
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n - 2; c++) {
        const v = Math.abs(board[r][c]);
        if (v !== 0 && Math.abs(board[r][c + 1]) === v && Math.abs(board[r][c + 2]) === v) {
          board[r][c] = -v;
          board[r][c + 1] = -Math.abs(board[r][c + 1]);
          board[r][c + 2] = -Math.abs(board[r][c + 2]);
          crushed = true;
        }
      }
    }

    // mark vertical triples
    for (let c = 0; c < n; c++) {
      for (let r = 0; r < m - 2; r++) {
        const v = Math.abs(board[r][c]);
        if (v !== 0 && Math.abs(board[r + 1][c]) === v && Math.abs(board[r + 2][c]) === v) {
          board[r][c] = -v;
          board[r + 1][c] = -Math.abs(board[r + 1][c]);
          board[r + 2][c] = -Math.abs(board[r + 2][c]);
          crushed = true;
        }
      }
    }

    if (!crushed) break;

    // convert marked (negative) to 0
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        if (board[r][c] < 0) board[r][c] = 0;
      }
    }

    // apply gravity column by column
    for (let c = 0; c < n; c++) {
      let write = m - 1;
      for (let r = m - 1; r >= 0; r--) {
        if (board[r][c] > 0) {
          board[write][c] = board[r][c];
          if (write !== r) board[r][c] = 0; // optional clean-up
          write--;
        }
      }
      // fill remaining cells with 0
      for (let r = write; r >= 0; r--) board[r][c] = 0;
    }
  }

  return board;
}

