Use Kadane's algorithm: scan once while keeping the maximum subarray sum ending at the current position and a global maximum, updating current = max(num, current + num) and global = max(global, current).

```typescript
function maxSubArray(nums: number[]): number {
  // Constraints guarantee nums.length >= 1, but handle empty defensively
  if (nums.length === 0) return 0;

  let current: number = nums[0];
  let best: number = nums[0];

  for (let i = 1; i < nums.length; i++) {
    // Either extend the current subarray or start fresh at nums[i]
    current = Math.max(nums[i], current + nums[i]);
    // Update best seen so far
    best = Math.max(best, current);
  }

  return best;
}

