Iteratively construct each row from the previous row: initialize each row with 1s and fill interior entries as sums of adjacent values from the preceding row.

```typescript
function generate(numRows: number): number[][] {
    const triangle: number[][] = [];
    for (let row = 0; row < numRows; row++) {
        // create a row of length row+1 filled with 1s
        const current: number[] = new Array(row + 1).fill(1);
        if (row > 1) {
            const prev = triangle[row - 1];
            for (let j = 1; j < row; j++) {
                current[j] = prev[j - 1] + prev[j];
            }
        }
        triangle.push(current);
    }
    return triangle;
}

