Build a trie of folders, compute a post-order serialization for each subtree (sorting child serializations) and count them, then collect paths while skipping any subtree whose serialization occurs more than once.

```typescript
function deleteDuplicateFolder(paths: string[][]): string[][] {
  class Node {
    name: string;
    children: Map<string, Node> = new Map();
    serial: string = "";
    constructor(name: string) { this.name = name; }
  }

  const root = new Node("");
  // Build trie
  for (const p of paths) {
    let cur = root;
    for (const name of p) {
      if (!cur.children.has(name)) cur.children.set(name, new Node(name));
      cur = cur.children.get(name)!;
    }
  }

  // Serialize subtrees (post-order) and count serializations (exclude root)
  const serialCount = new Map<string, number>();
  function dfsSerial(node: Node): string {
    if (node.children.size === 0) {
      node.serial = "";
    } else {
      const parts: string[] = [];
      for (const child of node.children.values()) {
        const s = dfsSerial(child);
        parts.push(child.name + "(" + s + ")");
      }
      parts.sort();
      node.serial = parts.join("");
    }
    if (node !== root) serialCount.set(node.serial, (serialCount.get(node.serial) || 0) + 1);
    return node.serial;
  }
  dfsSerial(root);

  // Collect remaining paths, skipping any subtree whose serialization count > 1
  const ans: string[][] = [];
  const path: string[] = [];
  function dfsCollect(node: Node) {
    for (const child of node.children.values()) {
      if (serialCount.get(child.serial) > 1) continue; // delete this subtree
      path.push(child.name);
      ans.push([...path]);
      dfsCollect(child);
      path.pop();
    }
  }
  dfsCollect(root);
  return ans;
}

