Greedily remove occurrences of the higher-value pair first (using a stack or in-place write pointer), then remove the other pair on the remaining string, summing points.

```typescript
function maximumGain(s: string, x: number, y: number): number {
  const remove = (str: string, target: string, pts: number): [string, number] => {
    const arr = str.split('');
    let write = 0;
    let score = 0;
    for (let read = 0; read < arr.length; read++) {
      arr[write++] = arr[read];
      if (write >= 2 && arr[write - 2] === target[0] && arr[write - 1] === target[1]) {
        write -= 2;
        score += pts;
      }
    }
    return [arr.slice(0, write).join(''), score];
  };

  let total = 0;
  if (x >= y) {
    const [afterFirst, score1] = remove(s, 'ab', x);
    total += score1;
    const [, score2] = remove(afterFirst, 'ba', y);
    total += score2;
  } else {
    const [afterFirst, score1] = remove(s, 'ba', y);
    total += score1;
    const [, score2] = remove(afterFirst, 'ab', x);
    total += score2;
  }
  return total;
}

// Example usage:
// console.log(maximumGain('cdbcbbaaabab', 4, 5)); // 19
