Sort nums and greedily assign each element the smallest feasible value >= previous_assigned + 1 (clamped to its [num-k, num+k] range), counting when you succeed in increasing the assigned value.

```typescript
function maxDistinct(nums: number[], k: number): number {
  if (nums.length === 0) return 0;
  nums.sort((a, b) => a - b);

  // Assign the smallest possible value to the first element
  let prev = nums[0] - k;
  let count = 1;

  for (let i = 1; i < nums.length; i++) {
    const low = nums[i] - k;
    const high = nums[i] + k;
    // Choose the smallest value >= prev + 1 but not exceeding high
    const ai = Math.min(Math.max(low, prev + 1), high);
    if (ai > prev) count++;
    prev = ai;
  }

  return count;
}

// Example
// console.log(maxDistinct([1,2,2,3,3,4], 2)); // 6
