Scan from the right to find the first decreasing element, swap it with the smallest element larger than it to its right, then reverse the suffix to get the next permutation.

```typescript
function nextPermutation(nums: number[]): void {
  const n = nums.length;
  // 1. Find first index i from right such that nums[i] < nums[i+1]
  let i = n - 2;
  while (i >= 0 && nums[i] >= nums[i + 1]) i--;

  // 2. If such index found, find j from right such that nums[j] > nums[i] and swap
  if (i >= 0) {
    let j = n - 1;
    while (nums[j] <= nums[i]) j--;
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }

  // 3. Reverse the suffix starting at i+1
  reverse(nums, i + 1, n - 1);
}

function reverse(arr: number[], left: number, right: number): void {
  while (left < right) {
    [arr[left], arr[right]] = [arr[right], arr[left]];
    left++;
    right--;
  }
}

