Collect all positive numbers into a hash set to enforce uniqueness and return their sum; if there are no positive numbers, return the maximum element of the array.

```typescript
function maximumUniqueSubarrayAfterDeletion(nums: number[]): number {
  const seen = new Set<number>();
  let sum = 0;
  let hasPositive = false;
  let maxVal = -Infinity;

  for (const x of nums) {
    if (x > 0) {
      if (!seen.has(x)) {
        seen.add(x);
        sum += x;
        hasPositive = true;
      }
    }
    if (x > maxVal) maxVal = x;
  }

  return hasPositive ? sum : maxVal;
}

