Count frequency differences, collect excess items from each basket, sort them and greedily pair the smallest excess from one side with the largest from the other, paying min(min(a,b), 2*globalMin) per pair.

```typescript
function minCostToMakeEqual(basket1: number[], basket2: number[]): number {
  const count1 = new Map<number, number>();
  const count2 = new Map<number, number>();
  let globalMin = Infinity;

  for (const v of basket1) { count1.set(v, (count1.get(v) || 0) + 1); globalMin = Math.min(globalMin, v); }
  for (const v of basket2) { count2.set(v, (count2.get(v) || 0) + 1); globalMin = Math.min(globalMin, v); }

  const keys = new Set<number>();
  for (const k of count1.keys()) keys.add(k);
  for (const k of count2.keys()) keys.add(k);

  const excessA: number[] = []; // items to move from basket1 -> basket2
  const excessB: number[] = []; // items to move from basket2 -> basket1

  for (const k of keys) {
    const c1 = count1.get(k) || 0;
    const c2 = count2.get(k) || 0;
    if ((c1 + c2) % 2 !== 0) return -1; // impossible
    const diff = c1 - c2;
    if (diff > 0) {
      const times = diff / 2;
      for (let i = 0; i < times; i++) excessA.push(k);
    } else if (diff < 0) {
      const times = (-diff) / 2;
      for (let i = 0; i < times; i++) excessB.push(k);
    }
  }

  if (excessA.length !== excessB.length) return -1; // safety check

  excessA.sort((a, b) => a - b);
  excessB.sort((a, b) => a - b);

  let cost = 0;
  const m = excessA.length;
  for (let i = 0; i < m; i++) {
    const a = excessA[i];
    const b = excessB[m - 1 - i]; // pair smallest a with largest b
    const direct = Math.min(a, b);
    const viaGlobal = 2 * globalMin;
    cost += Math.min(direct, viaGlobal);
  }

  return cost;
}

// Example usage:
// console.log(minCostToMakeEqual([4,2,2,2], [1,4,1,2])); // 1
