Use four boundaries (top, bottom, left, right) and repeatedly traverse the current top row, right column, bottom row (if remaining), and left column (if remaining), shrinking boundaries inward.

```typescript
function spiralOrder(matrix: number[][]): number[] {
  if (matrix.length === 0) return [];
  const m = matrix.length;
  const n = matrix[0].length;
  const result: number[] = [];

  let top = 0, bottom = m - 1;
  let left = 0, right = n - 1;

  while (top <= bottom && left <= right) {
    // traverse from left to right along the top row
    for (let col = left; col <= right; col++) result.push(matrix[top][col]);
    top++;

    // traverse from top to bottom along the right column
    for (let row = top; row <= bottom; row++) result.push(matrix[row][right]);
    right--;

    // traverse from right to left along the bottom row, if still within bounds
    if (top <= bottom) {
      for (let col = right; col >= left; col--) result.push(matrix[bottom][col]);
      bottom--;
    }

    // traverse from bottom to top along the left column, if still within bounds
    if (left <= right) {
      for (let row = bottom; row >= top; row--) result.push(matrix[row][left]);
      left++;
    }
  }

  return result;
}
