Use a doubly-linked list of buckets where each bucket stores all keys with the same frequency, plus a hash map from key to its bucket, so inc/dec move keys between adjacent buckets (creating/removing buckets as needed) in O(1) average time.

```typescript
class Bucket {
  freq: number;
  keys: Set<string>;
  prev: Bucket | null;
  next: Bucket | null;

  constructor(freq: number) {
    this.freq = freq;
    this.keys = new Set();
    this.prev = null;
    this.next = null;
  }
}

class AllOne {
  private head: Bucket;
  private tail: Bucket;
  private keyToBucket: Map<string, Bucket>;

  constructor() {
    this.head = new Bucket(0); // dummy head
    this.tail = new Bucket(0); // dummy tail
    this.head.next = this.tail;
    this.tail.prev = this.head;
    this.keyToBucket = new Map();
  }

  private insertBucketAfter(prev: Bucket, bucket: Bucket): void {
    bucket.prev = prev;
    bucket.next = prev.next;
    prev.next!.prev = bucket;
    prev.next = bucket;
  }

  private removeBucket(bucket: Bucket): void {
    bucket.prev!.next = bucket.next;
    bucket.next!.prev = bucket.prev;
    bucket.prev = null;
    bucket.next = null;
  }

  inc(key: string): void {
    const cur = this.keyToBucket.get(key);
    if (!cur) {
      // key is new, place into freq 1 bucket after head
      const first = this.head.next!;
      if (first === this.tail || first.freq !== 1) {
        const b = new Bucket(1);
        b.keys.add(key);
        this.insertBucketAfter(this.head, b);
        this.keyToBucket.set(key, b);
      } else {
        first.keys.add(key);
        this.keyToBucket.set(key, first);
      }
    } else {
      const next = cur.next!;
      const targetFreq = cur.freq + 1;
      // move key to next frequency bucket
      if (next === this.tail || next.freq !== targetFreq) {
        const b = new Bucket(targetFreq);
        b.keys.add(key);
        this.insertBucketAfter(cur, b);
        this.keyToBucket.set(key, b);
      } else {
        next.keys.add(key);
        this.keyToBucket.set(key, next);
      }
      // remove key from current bucket
      cur.keys.delete(key);
      if (cur.keys.size === 0) this.removeBucket(cur);
    }
  }

  dec(key: string): void {
    const cur = this.keyToBucket.get(key);
    if (!cur) return; // guaranteed key exists per problem, but safe

    if (cur.freq === 1) {
      // remove key entirely
      cur.keys.delete(key);
      this.keyToBucket.delete(key);
      if (cur.keys.size === 0) this.removeBucket(cur);
      return;
    }

    const prev = cur.prev!;
    const targetFreq = cur.freq - 1;
    if (prev === this.head || prev.freq !== targetFreq) {
      const b = new Bucket(targetFreq);
      b.keys.add(key);
      this.insertBucketAfter(prev, b);
      this.keyToBucket.set(key, b);
    } else {
      prev.keys.add(key);
      this.keyToBucket.set(key, prev);
    }

    cur.keys.delete(key);
    if (cur.keys.size === 0) this.removeBucket(cur);
  }

  getMaxKey(): string {
    if (this.tail.prev === this.head) return "";
    const last = this.tail.prev!;
    const it = last.keys.values().next();
    return it.done ? "" : it.value;
  }

  getMinKey(): string {
    if (this.head.next === this.tail) return "";
    const first = this.head.next!;
    const it = first.keys.values().next();
    return it.done ? "" : it.value;
  }
}

