Use a two-phase method: eliminate non-celebrities in O(n) by keeping a single candidate (if candidate knows i, candidate <- i), then verify the candidate by checking they know no one and everyone knows them.

```typescript
declare function knows(a: number, b: number): boolean;

export function findCelebrity(n: number): number {
  // Phase 1: find a candidate
  let candidate = 0;
  for (let i = 1; i < n; i++) {
    if (knows(candidate, i)) {
      // candidate can't be a celebrity
      candidate = i;
    }
  }

  // Phase 2: verify candidate
  for (let i = 0; i < n; i++) {
    if (i === candidate) continue;
    // candidate should know nobody, and everyone should know candidate
    if (knows(candidate, i) || !knows(i, candidate)) {
      return -1;
    }
  }

  return candidate;
}

