Use two pointers from both ends and on the first mismatch try skipping either the left or the right character and check if the remaining substring is a palindrome.

```typescript
function validPalindrome(s: string): boolean {
  let i = 0, j = s.length - 1;

  const isPalindrome = (l: number, r: number): boolean => {
    while (l < r) {
      if (s[l] !== s[r]) return false;
      l++; r--;
    }
    return true;
  };

  while (i < j) {
    if (s[i] === s[j]) {
      i++; j--;
    } else {
      // Try deleting one character: either skip left or skip right
      return isPalindrome(i + 1, j) || isPalindrome(i, j - 1);
    }
  }

  return true;
}

