For each black cell, increment the count for each of the (up to) four 2x2 blocks that include it (using their top-left coordinate as a key in a map), then compute arr[1..4] from the map and set arr[0] = totalBlocks - sum(arr[1..4]).

```typescript
function numberOfBlackBlocks(m: number, n: number, coordinates: number[][]): number[] {
  const map = new Map<string, number>();

  // For each black cell, it can belong to up to 4 different 2x2 blocks
  for (const [x, y] of coordinates) {
    for (const dx of [-1, 0]) {
      for (const dy of [-1, 0]) {
        const tx = x + dx;
        const ty = y + dy;
        if (tx >= 0 && tx < m - 1 && ty >= 0 && ty < n - 1) {
          const key = `${tx},${ty}`;
          map.set(key, (map.get(key) ?? 0) + 1);
        }
      }
    }
  }

  const res = new Array(5).fill(0);
  let nonZeroBlocks = 0;
  for (const cnt of map.values()) {
    res[cnt]++;
    nonZeroBlocks++;
  }

  const totalBlocks = (m - 1) * (n - 1);
  res[0] = totalBlocks - nonZeroBlocks;
  return res;
}

