Count frequencies of 0/1/2 separately for Y-cells and non-Y-cells, then try all 6 ordered pairs of distinct values (Y-value, non-Y-value) and pick the minimum changes needed.

```typescript
function minOperations(grid: number[][]): number {
  const n = grid.length;
  const mid = Math.floor(n / 2);
  const yCount = [0, 0, 0];
  const nonCount = [0, 0, 0];
  let totalY = 0, totalNon = 0;

  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      const val = grid[r][c];
      const isDiagonalToCenter = (r <= mid) && (r === c || r + c === n - 1);
      const isVerticalFromCenter = (r >= mid) && (c === mid);
      const isY = isDiagonalToCenter || isVerticalFromCenter;
      if (isY) {
        yCount[val]++;
        totalY++;
      } else {
        nonCount[val]++;
        totalNon++;
      }
    }
  }

  let ans = Number.POSITIVE_INFINITY;
  for (let a = 0; a <= 2; a++) {
    for (let b = 0; b <= 2; b++) {
      if (a === b) continue;
      const changes = (totalY - yCount[a]) + (totalNon - nonCount[b]);
      if (changes < ans) ans = changes;
    }
  }
  return ans;
}

