Sort records by timestamp, group sites per user, generate all unique 3-site sequences per user and count them across users, then pick the pattern with max count (lexicographically smallest on ties).

```typescript
function mostVisitedPattern(username: string[], timestamp: number[], website: string[]): string[] {
  const n = username.length;
  const records: { user: string; time: number; site: string }[] = [];
  for (let i = 0; i < n; i++) records.push({ user: username[i], time: timestamp[i], site: website[i] });

  // sort by time
  records.sort((a, b) => a.time - b.time);

  // group sites per user in chronological order
  const usersMap = new Map<string, string[]>();
  for (const r of records) {
    if (!usersMap.has(r.user)) usersMap.set(r.user, []);
    usersMap.get(r.user)!.push(r.site);
  }

  // pattern -> count of distinct users who had that pattern
  const patternCount = new Map<string, number>();

  for (const [user, sites] of usersMap.entries()) {
    const m = sites.length;
    if (m < 3) continue;
    const seen = new Set<string>(); // dedupe patterns per user
    for (let i = 0; i < m - 2; i++) {
      for (let j = i + 1; j < m - 1; j++) {
        for (let k = j + 1; k < m; k++) {
          const key = `${sites[i]}|${sites[j]}|${sites[k]}`;
          if (!seen.has(key)) {
            seen.add(key);
            patternCount.set(key, (patternCount.get(key) || 0) + 1);
          }
        }
      }
    }
  }

  // pick best pattern by count, then lexicographically
  let bestPattern = '';
  let bestCount = 0;
  const lexLess = (a: string, b: string) => {
    const A = a.split('|'), B = b.split('|');
    for (let i = 0; i < 3; i++) {
      if (A[i] < B[i]) return true;
      if (A[i] > B[i]) return false;
    }
    return false;
  };

  for (const [pat, cnt] of patternCount.entries()) {
    if (cnt > bestCount || (cnt === bestCount && (bestPattern === '' || lexLess(pat, bestPattern)))) {
      bestPattern = pat;
      bestCount = cnt;
    }
  }

  return bestPattern ? bestPattern.split('|') : [];
}

```

Use a two-pointer (sliding window) with a HashSet to maintain the current window of unique values, expanding the right pointer and shrinking the left pointer on duplicates while tracking the running sum and maximum sum.

```typescript
function maximumUniqueSubarray(nums: number[]): number {
  const seen = new Set<number>();
  let start = 0;
  let currentSum = 0;
  let maxSum = 0;

  for (let end = 0; end < nums.length; end++) {
    const val = nums[end];

    // If val is already in window, shrink from the left until it's removed
    while (seen.has(val)) {
      seen.delete(nums[start]);
      currentSum -= nums[start];
      start++;
    }

    // Add the new unique value
    seen.add(val);
    currentSum += val;

    // Update max
    if (currentSum > maxSum) maxSum = currentSum;
  }

  return maxSum;
}

// Example
