Prune all leaves that cannot affect coin collection (leaves with no coin), then remove leaves two more rounds to account for the "distance-2 collection" rule, and the remaining edges (times two) is the minimal travel.

```typescript
function collectCoins(coins: number[], edges: number[][]): number {
  const n = coins.length;
  if (n === 0) return 0;

  const adj: number[][] = Array.from({ length: n }, () => []);
  const degree: number[] = Array(n).fill(0);
  for (const [u, v] of edges) {
    adj[u].push(v);
    adj[v].push(u);
    degree[u]++;
    degree[v]++;
  }

  const removed: boolean[] = Array(n).fill(false);
  const q: number[] = [];
  // Initial prune: remove leaves (degree <= 1) that have no coin
  for (let i = 0; i < n; i++) {
    if (degree[i] <= 1 && coins[i] === 0) q.push(i);
  }
  let qi = 0;
  while (qi < q.length) {
    const u = q[qi++];
    if (removed[u]) continue;
    removed[u] = true;
    for (const v of adj[u]) {
      if (removed[v]) continue;
      degree[v]--;
      if (degree[v] === 1 && coins[v] === 0) q.push(v);
    }
  }

  // If all nodes removed, no travel needed
  // Now do two rounds of leaf removal to simulate collecting coins within distance 2
  let leaves: number[] = [];
  for (let i = 0; i < n; i++) {
    if (!removed[i] && degree[i] === 1) leaves.push(i);
  }

  for (let round = 0; round < 2; round++) {
    if (leaves.length === 0) break;
    const nextLeaves: number[] = [];
    for (const u of leaves) {
      if (removed[u]) continue;
      removed[u] = true;
      for (const v of adj[u]) {
        if (removed[v]) continue;
        degree[v]--;
        if (degree[v] === 1) nextLeaves.push(v);
      }
    }
    leaves = nextLeaves;
  }

  // Count remaining edges and each must be traversed twice
  let remainingEdges = 0;
  for (let i = 0; i < n; i++) {
    if (!removed[i]) remainingEdges += degree[i];
  }
  // each edge counted twice in degrees
  remainingEdges = Math.floor(remainingEdges / 2);
  return remainingEdges * 2;
}

// Example usage:
// console.log(collectCoins([1,0,0,0,0,1], [[0,1],[1,2],[2,3],[3,4],[4,5]])); // 2
```

Use recursive backtracking: pick any two numbers, replace them with every possible result of applying the four operators (considering order for non-commutative ops), and recurse until one value remains which is checked approximately against 24.

```typescript
function judgePoint24(cards: number[]): boolean {
  const EPS = 1e-6;

  function dfs(nums: number[]): boolean {
    if (nums.length === 1) return Math.abs(nums[0] - 24) < EPS;

    const n = nums.length;
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const a = nums[i];
        const b = nums[j];
        // build remaining list
        const nextBase: number[] = [];
        for (let k = 0; k < n; k++) if (k !== i && k !== j) nextBase.push(nums[k]);

        const candidates: number[] = [a + b, a - b, b - a, a * b];
        if (Math.abs(b) > EPS) candidates.push(a / b);
        if (Math.abs(a) > EPS) candidates.push(b / a);

        for (const c of candidates) {
          nextBase.push(c);
          if (dfs(nextBase)) return true;
          nextBase.pop();
        }
      }
    }
    return false;
  }

  return dfs(cards.map(x => x));
}

// Example usage:
// console.log(judgePoint24([4,1,8,7])); // true
