Simulate the process: for each fruit left-to-right, scan baskets left-to-right to find the first available basket with capacity >= fruit, mark that basket used, and count fruits that cannot be placed.

```typescript
function fruitsIntoBaskets(fruits: number[], baskets: number[]): number {
  const n = fruits.length;
  let unplaced = 0;

  // We mutate baskets to mark used baskets by setting capacity to 0.
  for (let i = 0; i < n; i++) {
    const need = fruits[i];
    let placed = false;
    for (let j = 0; j < n; j++) {
      if (baskets[j] >= need) {
        // place this fruit type in basket j and mark basket as used
        baskets[j] = 0;
        placed = true;
        break;
      }
    }
    if (!placed) unplaced++;
  }

  return unplaced;
}

