Use three pointers from the end: p1 at m-1, p2 at n-1, and p at m+n-1, and repeatedly write the larger of nums1[p1] and nums2[p2] into nums1[p] until nums2 is exhausted.

```typescript
function merge(nums1: number[], m: number, nums2: number[], n: number[]): void {
  let p1 = m - 1;
  let p2 = n - 1;
  let p = m + n - 1;

  // Fill from the end to avoid overwriting elements in nums1
  while (p2 >= 0) {
    if (p1 >= 0 && nums1[p1] > nums2[p2]) {
      nums1[p] = nums1[p1];
      p1--;
    } else {
      nums1[p] = nums2[p2];
      p2--;
    }
    p--;
  }
}

