Use a sweep-line: add +1 at each interval start and -1 at end+1, sort event keys, then scan accumulating brightness and record the earliest position where brightness becomes maximal.

```typescript
function brightestPosition(lights: number[][]): number {
  const events = new Map<number, number>();

  for (const [pos, range] of lights) {
    const start = pos - range;
    const endPlus = pos + range + 1; // use end+1 to make intervals inclusive
    events.set(start, (events.get(start) ?? 0) + 1);
    events.set(endPlus, (events.get(endPlus) ?? 0) - 1);
  }

  const keys = Array.from(events.keys()).sort((a, b) => a - b);
  let curr = 0;
  let bestBrightness = -1; // brightness is non-negative, so -1 is safe initial
  let bestPos = 0;

  for (const key of keys) {
    curr += events.get(key)!; // apply delta at this coordinate
    if (curr > bestBrightness) {
      bestBrightness = curr;
      bestPos = key; // this key is the smallest position that attains this brightness
    }
  }

  return bestPos;
}

