Single-pass scan keeping currentNumber, lastNumber and result: apply * and / immediately to lastNumber, and defer + and - by adding lastNumber to result when a new +/− is encountered.

```typescript
function calculate(s: string): number {
  // append a sentinel operator to force processing of the last number
  s = s + '+';
  let currentNumber = 0;
  let lastNumber = 0; // last evaluated value that will be added to result later
  let result = 0;
  let operation = '+'; // previous operation

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === ' ') continue;

    if (ch >= '0' && ch <= '9') {
      currentNumber = currentNumber * 10 + (ch.charCodeAt(0) - 48);
    } else {
      // ch is an operator (+ - * /) - process the previous operation
      if (operation === '+') {
        result += lastNumber;
        lastNumber = currentNumber;
      } else if (operation === '-') {
        result += lastNumber;
        lastNumber = -currentNumber;
      } else if (operation === '*') {
        lastNumber = lastNumber * currentNumber;
      } else if (operation === '/') {
        // truncate toward zero
        lastNumber = Math.trunc(lastNumber / currentNumber);
      }

      // reset for next number
      operation = ch;
      currentNumber = 0;
    }
  }

  return result + lastNumber;
}

// Example usage:
// console.log(calculate('3+2*2')); // 7
// console.log(calculate(' 3/2 ')); // 1
// console.log(calculate(' 3+5 / 2 ')); // 5
```

Use the Non-Adjacent Form (NAF) greedy loop: process LSB to MSB, when n is odd choose +1 or -1 based on n % 4 (prefer +1 when n%4==3 except n==1), count that as an operation, then divide by 2; even bits just shift.

```typescript
function minOperations(n: number): number {
  let ops = 0;
  while (n > 0) {
    if ((n & 1) === 0) {
      // even: shift right (no operation counted)
      n = n >> 1;
    } else {
      // odd: decide to add or subtract 1 at this bit (i.e., choose +2^i or -2^i)
      if (n === 1) {
        // final 1 -> one operation to remove it
        ops++;
        break;
      }
      // if n % 4 == 1, subtract 1 (choose -2^i); if n % 4 == 3, add 1 (choose +2^i)
      if ((n & 3) === 1) {
        ops++;
        n = (n - 1) >> 1;
      } else {
        ops++;
        n = (n + 1) >> 1;
      }
    }
  }
  return ops;
}

// Example
// console.log(minOperations(39)); // 3
// console.log(minOperations(54)); // 3
