Build a set of all prefixes of numbers in arr1 by repeatedly dividing by 10, then for each number in arr2 repeatedly shorten it until a prefix is found and track the maximum matched prefix length.

```typescript
function longestCommonPrefix(arr1: number[], arr2: number[]): number {
  const prefixes = new Set<number>();

  // Build all prefixes from arr1 (e.g., 12345 -> 12345, 1234, 123, 12, 1)
  for (const num of arr1) {
    let x = num;
    while (x > 0 && !prefixes.has(x)) {
      prefixes.add(x);
      x = Math.floor(x / 10);
    }
  }

  let longest = 0;
  // For each number in arr2, reduce until we find a stored prefix
  for (const num of arr2) {
    let x = num;
    while (x > 0 && !prefixes.has(x)) {
      x = Math.floor(x / 10);
    }
    if (x > 0) {
      const len = x.toString().length; // number of digits
      if (len > longest) longest = len;
    }
  }

  return longest;
}

