Use DP over hats (1..40) with a bitmask of which people are already assigned: dp(hat, mask) = ways to finish using hats hat..40, try skipping the hat or assigning it to any unassigned person who prefers it, and memoize.

```typescript
function numberWays(hats: number[][]): number {
  const MOD = 1000000007;
  const n = hats.length;
  const done = (1 << n) - 1;

  // Map hat -> list of people (0-based indices) who like that hat
  const hatsToPeople: number[][] = Array.from({ length: 41 }, () => []);
  for (let person = 0; person < n; person++) {
    for (const h of hats[person]) {
      if (h >= 1 && h <= 40) hatsToPeople[h].push(person);
    }
  }

  // memo[hat][mask] where hat in [1..41], mask in [0..(1<<n)-1]
  const H = 41; // we will use indices 1..40 and 41 as base
  const memo: number[][] = Array.from({ length: H + 1 }, () => new Array(1 << n).fill(-1));

  function dfs(hat: number, mask: number): number {
    if (mask === done) return 1;
    if (hat > 40) return 0;
    const cached = memo[hat][mask];
    if (cached !== -1) return cached;

    let ans = dfs(hat + 1, mask); // skip this hat
    for (const person of hatsToPeople[hat]) {
      if ((mask & (1 << person)) === 0) {
        ans = (ans + dfs(hat + 1, mask | (1 << person))) % MOD;
      }
    }

    memo[hat][mask] = ans;
    return ans;
  }

  return dfs(1, 0);
}

// Example usage:
// console.log(numberWays([[3,4],[4,5],[5]])); // 1
