Binary search the speed k between 1 and max(piles) and check for each candidate k whether the sum of ceil(pile/k) over all piles is <= h.

```typescript
function minEatingSpeed(piles: number[], h: number): number {
  let left = 1;
  let right = Math.max(...piles);

  const canFinish = (k: number): boolean => {
    let hours = 0;
    for (const p of piles) {
      // ceil division: (p + k - 1) // k
      hours += Math.floor((p + k - 1) / k);
      if (hours > h) return false; // early stop if already too slow
    }
    return hours <= h;
  };

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (canFinish(mid)) right = mid;
    else left = mid + 1;
  }

  return left;
}

