Process the number in 3-digit chunks (ones, thousands, millions, billions), convert each chunk to words with a helper for 0–999, then join chunks with the appropriate scale words.

```typescript
function numberToWords(num: number): string {
  if (num === 0) return 'Zero';

  const belowTwenty = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
  const thousands = ['', 'Thousand', 'Million', 'Billion'];

  const threeDigits = (n: number): string => {
    let res = '';
    if (n >= 100) {
      res += belowTwenty[Math.floor(n / 100)] + ' Hundred';
      n %= 100;
      if (n) res += ' ';
    }
    if (n >= 20) {
      res += tens[Math.floor(n / 10)];
      if (n % 10) res += ' ' + belowTwenty[n % 10];
    } else if (n > 0) {
      res += belowTwenty[n];
    }
    return res;
  };

  const parts: string[] = [];
  let i = 0;
  while (num > 0) {
    const chunk = num % 1000;
    if (chunk !== 0) {
      const chunkWords = threeDigits(chunk);
      const scale = thousands[i];
      parts.unshift(scale ? `${chunkWords} ${scale}` : chunkWords);
    }
    num = Math.floor(num / 1000);
    i++;
  }

  return parts.join(' ').replace(/\s+/g, ' ').trim();
}

// Example
console.log(numberToWords(1234567)); // "One Million Two Hundred Thirty Four Thousand Five Hundred Sixty Seven"
