Simulate day-by-day using an array newPeople[day] for people who learn the secret that day and maintain a sliding-window sum of currently-sharing people to compute new learners in O(1) per day.

```typescript
function peopleAwareOfSecret(n: number, delay: number, forget: number): number {
  const MOD = 1000000007;
  const newPeople = new Array<number>(n + 1).fill(0);
  newPeople[1] = 1; // day 1: one person learns the secret

  let sharers = 0; // current number of people who can share on this day

  for (let day = 2; day <= n; day++) {
    // people who learned on (day - delay) start sharing today
    if (day - delay >= 1) {
      sharers = (sharers + newPeople[day - delay]) % MOD;
    }
    // people who learned on (day - forget) forget today and can no longer share
    if (day - forget >= 1) {
      sharers = (sharers - newPeople[day - forget] + MOD) % MOD;
    }
    // number of new people who learn today equals current sharers
    newPeople[day] = sharers;
  }

  // count people who still remember on day n: those who learned in [n-forget+1, n]
  let result = 0;
  const start = Math.max(1, n - forget + 1);
  for (let d = start; d <= n; d++) {
    result = (result + newPeople[d]) % MOD;
  }
  return result;
}

// Example usage:
// console.log(peopleAwareOfSecret(6, 2, 4)); // 5
// console.log(peopleAwareOfSecret(4, 1, 3)); // 6
