Parse transactions into objects, group by name and sort each group by time, mark any with amount>1000 or any pair within 60 minutes in different cities as invalid, and return their original strings.

```typescript
type Tx = { name: string; time: number; amount: number; city: string; raw: string };

function invalidTransactions(transactions: string[]): string[] {
  const map = new Map<string, Tx[]>();
  const invalid = new Set<string>();

  for (const raw of transactions) {
    const [name, timeS, amountS, city] = raw.split(",");
    const time = Number(timeS);
    const amount = Number(amountS);
    const tx: Tx = { name, time, amount, city, raw };
    if (!map.has(name)) map.set(name, []);
    map.get(name)!.push(tx);
    if (amount > 1000) invalid.add(raw);
  }

  for (const [_, list] of map) {
    list.sort((a, b) => a.time - b.time);
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        if (list[j].time - list[i].time > 60) break; // beyond 60 minutes window
        if (list[i].city !== list[j].city) {
          invalid.add(list[i].raw);
          invalid.add(list[j].raw);
        }
      }
    }
  }

  return Array.from(invalid);
}

// Example usage:
// console.log(invalidTransactions(["alice,20,800,mtv","alice,50,100,beijing"]));
