Use a max-heap keyed by the marginal gain ((p+1)/(t+1) - p/t) of adding one student to a class, repeatedly pop the class with largest gain, add one student, recompute its gain and push it back until extraStudents are exhausted.

```typescript
function maxAverageRatio(classes: number[][], extraStudents: number): number {
  type Item = { p: number; t: number; gain: number };
  const gain = (p: number, t: number) => (p + 1) / (t + 1) - p / t;

  // Build initial items
  const items: Item[] = classes.map(([p, t]) => ({ p, t, gain: gain(p, t) }));

  // Max-heap implementation (by gain)
  class MaxHeap {
    arr: Item[];
    constructor(array: Item[]) {
      this.arr = array.slice();
      this.build();
    }
    size() { return this.arr.length; }
    build() {
      for (let i = Math.floor((this.arr.length - 1) / 2); i >= 0; i--) this.siftDown(i);
    }
    push(x: Item) {
      this.arr.push(x);
      this.siftUp(this.arr.length - 1);
    }
    pop(): Item | undefined {
      if (this.arr.length === 0) return undefined;
      const top = this.arr[0];
      const last = this.arr.pop()!;
      if (this.arr.length > 0) {
        this.arr[0] = last;
        this.siftDown(0);
      }
      return top;
    }
    peek(): Item | undefined { return this.arr[0]; }
    private siftUp(i: number) {
      let idx = i;
      while (idx > 0) {
        const parent = Math.floor((idx - 1) / 2);
        if (this.arr[idx].gain <= this.arr[parent].gain) break;
        [this.arr[idx], this.arr[parent]] = [this.arr[parent], this.arr[idx]];
        idx = parent;
      }
    }
    private siftDown(i: number) {
      const n = this.arr.length;
      let idx = i;
      while (true) {
        const l = idx * 2 + 1;
        const r = l + 1;
        let largest = idx;
        if (l < n && this.arr[l].gain > this.arr[largest].gain) largest = l;
        if (r < n && this.arr[r].gain > this.arr[largest].gain) largest = r;
        if (largest === idx) break;
        [this.arr[idx], this.arr[largest]] = [this.arr[largest], this.arr[idx]];
        idx = largest;
      }
    }
  }

  const heap = new MaxHeap(items);

  // Distribute extra students
  for (let k = 0; k < extraStudents; k++) {
    const top = heap.pop()!; // guaranteed non-empty
    // assign one student
    top.p += 1;
    top.t += 1;
    // recompute gain for next potential student and push back
    top.gain = gain(top.p, top.t);
    heap.push(top);
  }

  // Sum final pass ratios
  let sum = 0;
  for (const it of heap.arr) sum += it.p / it.t;
  return sum / classes.length;
}

// Example usage:
// console.log(maxAverageRatio([[1,2],[3,5],[2,2]], 2).toFixed(5)); // ~0.78333
