Greedily assign each sunny day to the earliest future drying need by keeping an ordered set (sorted list) of sunny-day indices and, when a lake rains again, binary-search the smallest sunny day after its last rain to dry it before the new rain.

```typescript
function avoidFlood(rains: number[]): number[] {
  const n = rains.length;
  const ans: number[] = new Array(n).fill(1); // default dry any lake (1) on unused sunny days
  const lastRain = new Map<number, number>(); // lake -> last day it rained
  const sunnyDays: number[] = []; // sorted list of indices of days with rains[i] == 0

  function upperBound(arr: number[], target: number): number {
    // first index with arr[idx] > target
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (arr[mid] <= target) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  for (let i = 0; i < n; i++) {
    const lake = rains[i];
    if (lake === 0) {
      // sunny day: record index, will choose which lake to dry later
      sunnyDays.push(i);
      // ans[i] stays 1 until possibly assigned to dry a specific lake
    } else {
      ans[i] = -1; // raining day
      if (!lastRain.has(lake)) {
        lastRain.set(lake, i);
      } else {
        const prev = lastRain.get(lake)!;
        // find a sunny day strictly after prev to dry this lake before day i
        const pos = upperBound(sunnyDays, prev);
        if (pos === sunnyDays.length) {
          // no available sunny day to dry this lake -> impossible
          return [];
        }
        const dryDayIdx = sunnyDays[pos];
        ans[dryDayIdx] = lake; // schedule drying of 'lake' on that sunny day
        // remove that sunny day from list
        sunnyDays.splice(pos, 1);
        // update last rain day for this lake
        lastRain.set(lake, i);
      }
    }
  }

  // any remaining sunnyDays can dry arbitrary lake (we left them as 1)
  return ans;
}

