Use a dummy (prehead) node and iterate through both lists, attaching the smaller current node each step and finally appending the remaining non-null list.

```typescript
class ListNode {
  val: number;
  next: ListNode | null;
  constructor(val?: number, next?: ListNode | null) {
    this.val = (val === undefined ? 0 : val);
    this.next = (next === undefined ? null : next);
  }
}

function mergeTwoLists(list1: ListNode | null, list2: ListNode | null): ListNode | null {
  const prehead = new ListNode(-1);
  let prev: ListNode = prehead;
  let l1 = list1;
  let l2 = list2;

  while (l1 !== null && l2 !== null) {
    if (l1.val <= l2.val) {
      prev.next = l1;
      l1 = l1.next;
    } else {
      prev.next = l2;
      l2 = l2.next;
    }
    prev = prev.next!;
  }

  // At most one of l1 and l2 can be non-null, so connect the remainder.
  prev.next = l1 !== null ? l1 : l2;

  return prehead.next;
}
