Use two hash maps: key -> node (stores key, value, freq) and freq -> doubly linked list of nodes (ordered by recency), maintain current min frequency; on access/update move node to the next freq list and update minFreq, evict from minFreq's list when needed.

```typescript
class Node {
  key: number;
  val: number;
  freq: number;
  prev: Node | null = null;
  next: Node | null = null;

  constructor(key: number, val: number) {
    this.key = key;
    this.val = val;
    this.freq = 1;
  }
}

class DoublyLinkedList {
  head: Node;
  tail: Node;
  size: number = 0;

  constructor() {
    this.head = new Node(-1, -1); // sentinel
    this.tail = new Node(-1, -1); // sentinel
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  // insert node right after head (most recent)
  pushFront(node: Node) {
    node.next = this.head.next;
    node.prev = this.head;
    if (this.head.next) this.head.next.prev = node;
    this.head.next = node;
    this.size++;
  }

  remove(node: Node) {
    if (!node.prev || !node.next) return;
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.prev = null;
    node.next = null;
    this.size--;
  }

  // remove least recently used (node right before tail)
  popTail(): Node | null {
    if (this.size === 0) return null;
    const node = this.tail.prev!;
    this.remove(node);
    return node;
  }

  isEmpty(): boolean {
    return this.size === 0;
  }
}

class LFUCache {
  private capacity: number;
  private size: number = 0;
  private minFreq: number = 0;
  private keyToNode: Map<number, Node> = new Map();
  private freqToList: Map<number, DoublyLinkedList> = new Map();

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  get(key: number): number {
    const node = this.keyToNode.get(key);
    if (!node) return -1;
    this.increaseFreq(node);
    return node.val;
  }

  put(key: number, value: number): void {
    if (this.capacity === 0) return;

    if (this.keyToNode.has(key)) {
      const node = this.keyToNode.get(key)!;
      node.val = value;
      this.increaseFreq(node);
      return;
    }

    if (this.size === this.capacity) {
      // evict least frequently used, tie -> least recently used
      const list = this.freqToList.get(this.minFreq)!;
      const nodeToRemove = list.popTail()!;
      this.keyToNode.delete(nodeToRemove.key);
      this.size--;
    }

    const newNode = new Node(key, value);
    this.keyToNode.set(key, newNode);
    let list = this.freqToList.get(1);
    if (!list) {
      list = new DoublyLinkedList();
      this.freqToList.set(1, list);
    }
    list.pushFront(newNode);
    this.minFreq = 1;
    this.size++;
  }

  private increaseFreq(node: Node) {
    const oldFreq = node.freq;
    const oldList = this.freqToList.get(oldFreq)!;
    oldList.remove(node);

    // if this was the only node with minFreq, increase minFreq
    if (oldFreq === this.minFreq && oldList.isEmpty()) {
      this.minFreq++;
    }

    node.freq++;
    let newList = this.freqToList.get(node.freq);
    if (!newList) {
      newList = new DoublyLinkedList();
      this.freqToList.set(node.freq, newList);
    }
    newList.pushFront(node);
  }
}

