Group numbers by their remainder modulo k, then greedily build the MEX starting from 0 by consuming one element from the bucket for remainder (mex % k) each time until that bucket is empty.

```typescript
function maximumMEX(nums: number[], value: number): number {
  // counts of each remainder modulo value
  const cnt = new Array<number>(value).fill(0);
  for (const x of nums) {
    const r = ((x % value) + value) % value; // normalize negative
    cnt[r]++;
  }

  let mex = 0;
  while (true) {
    const r = mex % value;
    if (cnt[r] > 0) {
      cnt[r]--;
      mex++;
    } else {
      break;
    }
  }
  return mex;
}

// Example usage:
// console.log(maximumMEX([1,-10,7,13,6,8], 5)); // 4
