Use row-by-row backtracking and prune placements by tracking used columns, diagonals (row - col) and anti-diagonals (row + col).

```typescript
function solveNQueens(n: number): string[][] {
  const res: string[][] = [];
  const cols = new Array<boolean>(n).fill(false);
  const diag = new Array<boolean>(2 * n).fill(false); // row - col + n
  const anti = new Array<boolean>(2 * n).fill(false); // row + col
  const queens = new Array<number>(n).fill(-1); // queens[row] = col

  function backtrack(row: number) {
    if (row === n) {
      // build board from queens positions
      const board = queens.map(col => '.'.repeat(col) + 'Q' + '.'.repeat(n - col - 1));
      res.push(board);
      return;
    }

    for (let col = 0; col < n; col++) {
      const d = row - col + n;
      const a = row + col;
      if (cols[col] || diag[d] || anti[a]) continue;

      cols[col] = diag[d] = anti[a] = true;
      queens[row] = col;

      backtrack(row + 1);

      // backtrack
      cols[col] = diag[d] = anti[a] = false;
      queens[row] = -1;
    }
  }

  backtrack(0);
  return res;
}

// Example usage:
// console.log(solveNQueens(4));
