Decompose n into its set-bit powers, compute prefix sums of the bit indices, and answer each query as 2^(sum of exponents in range) mod 1e9+7 using fast modular exponentiation.

```typescript
function rangeProductQueries(n: number, queries: number[][]): number[] {
  const MOD = 1000000007;

  // Decompose n into list of exponents k where 2^k is present (in non-decreasing order)
  const exps: number[] = [];
  let k = 0;
  let m = n;
  while (m > 0) {
    if (m & 1) exps.push(k);
    k++;
    m >>= 1;
  }

  // Prefix sums of exponents: pref[i] = sum of exps[0..i-1]
  const pref: number[] = new Array(exps.length + 1).fill(0);
  for (let i = 0; i < exps.length; i++) pref[i + 1] = pref[i] + exps[i];

  // Fast modular exponentiation
  function modPow(base: number, exp: number): number {
    let res = 1;
    let b = base % MOD;
    let e = exp;
    while (e > 0) {
      if (e & 1) res = (res * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return res;
  }

  const ans: number[] = [];
  for (const [l, r] of queries) {
    const expSum = pref[r + 1] - pref[l];
    ans.push(modPow(2, expSum));
  }
  return ans;
}

// Example
// console.log(rangeProductQueries(15, [[0,1],[2,2],[0,3]])); // [2,4,64]
