Use iterative binary search: at each mid compare nums[mid] and nums[mid+1] and move left if mid is on a descending slope (nums[mid] > nums[mid+1]) else move right, until l==r which is a peak.

```typescript
function findPeakElement(nums: number[]): number {
  let l = 0;
  let r = nums.length - 1;

  while (l < r) {
    const mid = Math.floor((l + r) / 2);
    // If mid is greater than its right neighbor, peak is in [l, mid]
    if (nums[mid] > nums[mid + 1]) {
      r = mid;
    } else {
      // Otherwise peak is in [mid+1, r]
      l = mid + 1;
    }
  }

  return l; // l == r is a peak index
}

// Example
// console.log(findPeakElement([1,2,3,1])); // 2
