Use a trie-like tree (each node maps names to child nodes) where each node has an isFile flag and a content string; traverse the path components to implement ls/mkdir/add/read efficiently.

```typescript
class FileNode {
  children: Map<string, FileNode>;
  isFile: boolean;
  content: string;
  constructor() {
    this.children = new Map<string, FileNode>();
    this.isFile = false;
    this.content = '';
  }
}

class FileSystem {
  root: FileNode;

  constructor() {
    this.root = new FileNode();
  }

  private traverse(path: string, create = false): FileNode | null {
    if (path === '/') return this.root;
    const parts = path.split('/').filter(p => p.length);
    let node = this.root;
    for (const part of parts) {
      if (!node.children.has(part)) {
        if (create) node.children.set(part, new FileNode());
        else return null;
      }
      node = node.children.get(part)!;
    }
    return node;
  }

  ls(path: string): string[] {
    if (path === '/') {
      return Array.from(this.root.children.keys()).sort();
    }
    const node = this.traverse(path, false)!;
    const parts = path.split('/').filter(p => p.length);
    const name = parts[parts.length - 1];
    if (node.isFile) {
      return [name];
    }
    return Array.from(node.children.keys()).sort();
  }

  mkdir(path: string): void {
    this.traverse(path, true);
  }

  addContentToFile(filePath: string, content: string): void {
    const node = this.traverse(filePath, true)!;
    node.isFile = true;
    node.content += content;
  }

  readContentFromFile(filePath: string): string {
    const node = this.traverse(filePath, false)!;
    return node.content;
  }
}

