Enumerate all partition patterns (three vertical strips, a vertical cut with one side split horizontally, and a horizontal cut with one side split vertically) across three rotations of the grid and compute the bounding rectangle area for each part, keeping the minimum total.

```typescript
function minAreaCoverThreeRectangles(origGrid: number[][]): number {
  const rotate90 = (g: number[][]): number[][] => {
    const n = g.length, m = g[0].length;
    const ng: number[][] = Array.from({ length: m }, () => Array(n).fill(0));
    for (let i = 0; i < n; ++i) {
      for (let j = 0; j < m; ++j) ng[j][n - 1 - i] = g[i][j];
    }
    return ng;
  };

  let best = Infinity;
  let grid = origGrid.map(row => row.slice()); // copy

  // We'll examine 3 orientations: 0, 90, 180 degrees (rotating twice covers all 6 symmetric partition types)
  for (let rot = 0; rot < 3; ++rot) {
    const n = grid.length, m = grid[0].length;

    const boundingArea = (r1: number, r2: number, c1: number, c2: number): number => {
      if (r1 > r2 || c1 > c2) return 0;
      let found = false;
      let minR = n, maxR = -1, minC = m, maxC = -1;
      for (let i = r1; i <= r2; ++i) {
        for (let j = c1; j <= c2; ++j) {
          if (grid[i][j] === 1) {
            found = true;
            if (i < minR) minR = i;
            if (i > maxR) maxR = i;
            if (j < minC) minC = j;
            if (j > maxC) maxC = j;
          }
        }
      }
      if (!found) return 0; // no ones in region
      return (maxR - minR + 1) * (maxC - minC + 1);
    };

    // Case 1: three vertical strips (two vertical cuts)
    for (let c1 = 0; c1 <= m - 3; ++c1) {
      for (let c2 = c1 + 1; c2 <= m - 2; ++c2) {
        const a1 = boundingArea(0, n - 1, 0, c1);
        const a2 = boundingArea(0, n - 1, c1 + 1, c2);
        const a3 = boundingArea(0, n - 1, c2 + 1, m - 1);
        if (a1 > 0 && a2 > 0 && a3 > 0) best = Math.min(best, a1 + a2 + a3);
      }
    }

    // Case 2: vertical cut at c, left side split horizontally into two parts (left-top, left-bottom, right)
    for (let c = 0; c <= m - 2; ++c) {
      for (let r = 0; r <= n - 2; ++r) {
        const a1 = boundingArea(0, r, 0, c);         // left-top
        const a2 = boundingArea(r + 1, n - 1, 0, c); // left-bottom
        const a3 = boundingArea(0, n - 1, c + 1, m - 1); // right
        if (a1 > 0 && a2 > 0 && a3 > 0) best = Math.min(best, a1 + a2 + a3);
      }
    }

    // Case 3: horizontal cut at r, top side split vertically into two parts (top-left, top-right, bottom)
    for (let r = 0; r <= n - 2; ++r) {
      for (let c = 0; c <= m - 2; ++c) {
        const a1 = boundingArea(0, r, 0, c);         // top-left
        const a2 = boundingArea(0, r, c + 1, m - 1); // top-right
        const a3 = boundingArea(r + 1, n - 1, 0, m - 1); // bottom
        if (a1 > 0 && a2 > 0 && a3 > 0) best = Math.min(best, a1 + a2 + a3);
      }
    }

    // rotate for next orientation
    grid = rotate90(grid);
  }

  return best === Infinity ? -1 : best;
}

// Example usage:
// console.log(minAreaCoverThreeRectangles([[1,0,1],[1,1,1]])); // 5

