Transpose the matrix (swap matrix[i][j] with matrix[j][i]) and then reverse each row in-place.

```typescript
function rotate(matrix: number[][]): void {
  const n = matrix.length;

  // Transpose: swap matrix[i][j] with matrix[j][i] for j > i
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const tmp = matrix[i][j];
      matrix[i][j] = matrix[j][i];
      matrix[j][i] = tmp;
    }
  }

  // Reverse each row
  for (let i = 0; i < n; i++) {
    let l = 0, r = n - 1;
    while (l < r) {
      const tmp = matrix[i][l];
      matrix[i][l] = matrix[i][r];
      matrix[i][r] = tmp;
      l++; r--;
    }
  }
}

// Example usage:
// const mat = [[1,2,3],[4,5,6],[7,8,9]];
