Traverse indices from right to left while tracking the nearest index to the right where each bit is 1 (pos for each bit); for index i, the right boundary must reach the maximum of those pos[bit] for bits that are 0 in nums[i], giving the minimal subarray length.

```typescript
function smallestSubarrays(nums: number[]): number[] {
  const n = nums.length;
  const BITS = 31; // enough for nums[i] up to 1e9
  const pos: number[] = new Array(BITS).fill(-1); // nearest index to the right where bit is 1
  const ans: number[] = new Array(n).fill(1);

  for (let i = n - 1; i >= 0; --i) {
    let reach = i;
    // For bits that are 0 in nums[i], we may need to extend to the nearest pos where that bit is 1
    for (let b = 0; b < BITS; ++b) {
      if (((nums[i] >>> b) & 1) === 0 && pos[b] !== -1) {
        reach = Math.max(reach, pos[b]);
      }
    }
    ans[i] = reach - i + 1;
    // Update positions for bits that are 1 in nums[i]
    for (let b = 0; b < BITS; ++b) {
      if (((nums[i] >>> b) & 1) === 1) pos[b] = i;
    }
  }

  return ans;
}

// Example usage:
// console.log(smallestSubarrays([1,0,2,1,3])); // [3,3,2,2,1]
