Sort the array and for each index k as the largest side use a two-pointer scan (i from left, j from k-1) to count in O(n^2) time the pairs with nums[i] + nums[j] > nums[k].

```typescript
function validTriangleNumber(nums: number[]): number {
  const n = nums.length;
  if (n < 3) return 0;
  nums.sort((a, b) => a - b);
  let count = 0;

  for (let k = n - 1; k >= 2; k--) {
    let i = 0;
    let j = k - 1;
    while (i < j) {
      if (nums[i] + nums[j] > nums[k]) {
        // All elements from i..j-1 paired with j will also satisfy
        count += j - i;
        j--;
      } else {
        i++;
      }
    }
  }

  return count;
}

// Example
// console.log(validTriangleNumber([2,2,3,4])); // 3
