Split the path by '/', use a stack to push valid directory names, ignore '' and '.', pop for '..', then join the stack with '/' and prefix with '/' to form the canonical path.

```typescript
function simplifyPath(path: string): string {
  const parts = path.split('/');
  const stack: string[] = [];

  for (const part of parts) {
    if (!part || part === '.') continue; // skip empty and current-dir
    if (part === '..') {
      if (stack.length) stack.pop(); // go up one level if possible
    } else {
      stack.push(part); // valid directory name
    }
  }

  return '/' + stack.join('/');
}

// Example usage:
// console.log(simplifyPath('/.../a/../b/c/../d/./')); // '/.../b/d'
