Use divide-and-conquer: if a rectangle contains any ship, split it into four sub-rectangles (by mid x/y) and recursively count ships in each, stopping when a sub-rectangle is empty or is a single point.

```typescript
interface Sea {
  // Returns true if there is at least one ship in the rectangle (inclusive)
  hasShips(topRight: number[], bottomLeft: number[]): boolean;
}

function countShips(sea: Sea, topRight: number[], bottomLeft: number[]): number {
  const [x1, y1] = bottomLeft;
  const [x2, y2] = topRight;

  // invalid rectangle
  if (x1 > x2 || y1 > y2) return 0;

  // if no ships in this rectangle, prune
  if (!sea.hasShips(topRight, bottomLeft)) return 0;

  // if the rectangle is a single point and hasShips returned true, it's one ship
  if (x1 === x2 && y1 === y2) return 1;

  const midX = Math.floor((x1 + x2) / 2);
  const midY = Math.floor((y1 + y2) / 2);

  // split into 4 sub-rectangles and sum their ship counts
  let count = 0;

  // bottom-left
  count += countShips(sea, [midX, midY], [x1, y1]);
  // bottom-right
  count += countShips(sea, [x2, midY], [midX + 1, y1]);
  // top-left
  count += countShips(sea, [midX, y2], [x1, midY + 1]);
  // top-right
  count += countShips(sea, [x2, y2], [midX + 1, midY + 1]);

  return count;
}

