Label each island with a unique id and precompute its size (via DFS/BFS), then for every 0 sum sizes of distinct neighboring islands (plus one) to get the best flip.

```typescript
function largestIsland(grid: number[][]): number {
  const n = grid.length;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]] as number[][];
  const islandSize = new Map<number, number>();
  let islandId = 2; // start ids at 2 to distinguish from 0/1

  // Label islands iteratively to avoid recursion depth issues
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === 1) {
        let size = 0;
        const stack: [number, number][] = [[r, c]];
        grid[r][c] = islandId;
        while (stack.length) {
          const [x, y] = stack.pop()!;
          size++;
          for (const [dr, dc] of dirs) {
            const nx = x + dr, ny = y + dc;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] === 1) {
              grid[nx][ny] = islandId;
              stack.push([nx, ny]);
            }
          }
        }
        islandSize.set(islandId, size);
        islandId++;
      }
    }
  }

  // If there were no islands at all, flipping any 0 gives area 1
  if (islandSize.size === 0) return 1;

  // Start with the largest existing island (in case there are no zeros)
  let result = 0;
  for (const s of islandSize.values()) result = Math.max(result, s);

  // Try flipping each 0 and sum distinct neighboring island sizes
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === 0) {
        const seen = new Set<number>();
        let cur = 1; // the flipped cell
        for (const [dr, dc] of dirs) {
          const nr = r + dr, nc = c + dc;
          if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
            const id = grid[nr][nc];
            if (id > 1 && !seen.has(id)) {
              seen.add(id);
              cur += islandSize.get(id)!;
            }
          }
        }
        result = Math.max(result, cur);
      }
    }
  }

  return result;
}

```

Root the tree, compute subtree XORs and entry/exit times with one DFS, then enumerate all pairs of child-edges (O(n^2)) and use ancestor checks to compute the three component XORs for each pair.

```typescript
function minimumScore(nums: number[], edges: number[][]): number {
  const n = nums.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }

  const parent = new Array<number>(n).fill(-1);
  const tin = new Array<number>(n).fill(0);
  const tout = new Array<number>(n).fill(0);
  const subXor = new Array<number>(n).fill(0);
  let timer = 0;

  const dfs = (u: number, p: number) => {
    parent[u] = p;
    tin[u] = ++timer;
    subXor[u] = nums[u];
    for (const v of adj[u]) {
      if (v === p) continue;
      dfs(v, u);
      subXor[u] ^= subXor[v];
    }
    tout[u] = timer;
  };

  // root the tree at 0
  dfs(0, -1);
  const total = subXor[0];
  const isAncestor = (u: number, v: number) => tin[u] <= tin[v] && tout[v] <= tout[u];

  let ans = Infinity;
  // iterate over pairs of nodes representing the child side of removed edges
  // (skip root because there's no edge above it)
  for (let i = 1; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      let a: number, b: number, c: number;
      if (isAncestor(i, j)) {
        // i is ancestor of j: components are subtree(j), subtree(i)-subtree(j), rest
        a = subXor[j];
        b = subXor[i] ^ subXor[j];
        c = total ^ subXor[i];
      } else if (isAncestor(j, i)) {
        // j is ancestor of i
        a = subXor[i];
        b = subXor[j] ^ subXor[i];
        c = total ^ subXor[j];
      } else {
        // disjoint subtrees
        a = subXor[i];
        b = subXor[j];
        c = total ^ subXor[i] ^ subXor[j];
      }
      const mx = Math.max(a, b, c);
      const mn = Math.min(a, b, c);
      ans = Math.min(ans, mx - mn);
    }
  }

  return ans;
}

// Example usage:
// console.log(minimumScore([1,5,5,4,11], [[0,1],[1,2],[1,3],[3,4]])); // 9
```

Sort jobs by start time and use dynamic programming (bottom-up) where for each job you binary-search the next non-conflicting job and choose max(take current + dp[next], skip current).

```typescript
function jobScheduling(startTime: number[], endTime: number[], profit: number[]): number {
  const n = startTime.length;
  // pack jobs and sort by start time
  const jobs = startTime.map((s, i) => ({ s, e: endTime[i], p: profit[i] }));
  jobs.sort((a, b) => a.s - b.s);

  const starts = jobs.map(j => j.s);
  const dp: number[] = new Array(n + 1).fill(0); // dp[i] = max profit from jobs[i..n-1]

  const findNext = (target: number): number => {
    // first index with starts[idx] >= target
    let l = 0, r = n;
    while (l < r) {
      const mid = (l + r) >> 1;
      if (starts[mid] < target) l = mid + 1;
      else r = mid;
    }
    return l;
  };

  for (let i = n - 1; i >= 0; --i) {
    const nextIdx = findNext(jobs[i].e);
    const take = jobs[i].p + dp[nextIdx];
    const skip = dp[i + 1];
    dp[i] = Math.max(take, skip);
  }

  return dp[0];
}

// Example usage:
// console.log(jobScheduling([1,2,3,3], [3,4,5,6], [50,10,40,70])); // 120
```

Perform a single modified binary search: at each step determine which half (left or right) is sorted and decide which half can contain target, then narrow the search accordingly.

```typescript
function search(nums: number[], target: number): number {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);
    if (nums[mid] === target) return mid;

    // If left..mid is sorted
    if (nums[left] <= nums[mid]) {
      if (nums[left] <= target && target < nums[mid]) {
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    } else {
      // Otherwise mid..right must be sorted
      if (nums[mid] < target && target <= nums[right]) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  }

  return -1;
}

```

Enumerate the four possible parity patterns for even/odd positions in the subsequence and greedily build the longest subsequence matching each pattern in a single pass, taking the maximum.

```typescript
function longestValidSubsequence(nums: number[]): number {
  // Patterns: [parity at subsequence index 0, parity at subsequence index 1]
  // parity: 0 = even, 1 = odd
  const patterns: [number, number][] = [[0, 0], [1, 1], [1, 0], [0, 1]];
  let best = 0;

  for (const [p0, p1] of patterns) {
    let len = 0; // current length of subsequence for this pattern
    for (const x of nums) {
      const expected = (len % 2 === 0) ? p0 : p1;
      if ((x & 1) === expected) {
        len++;
      }
    }
    if (len > best) best = len;
  }

  return best;
}

// Example usage:
// console.log(longestValidSubsequence([1,2,3,4])); // 4
