Use a min-heap (priority queue) containing the current head of each list, repeatedly pop the smallest node and append it to the merged list, pushing the popped node's next when present.

```typescript
class ListNode {
  val: number;
  next: ListNode | null;
  constructor(val = 0, next: ListNode | null = null) {
    this.val = val;
    this.next = next;
  }
}

class MinHeap {
  private heap: ListNode[] = [];

  size(): number { return this.heap.length; }

  push(node: ListNode) {
    this.heap.push(node);
    this.siftUp(this.heap.length - 1);
  }

  pop(): ListNode | null {
    if (this.heap.length === 0) return null;
    const top = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.siftDown(0);
    }
    return top;
  }

  private siftUp(i: number) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (this.heap[i].val < this.heap[parent].val) {
        [this.heap[i], this.heap[parent]] = [this.heap[parent], this.heap[i]];
        i = parent;
      } else break;
    }
  }

  private siftDown(i: number) {
    const n = this.heap.length;
    while (true) {
      let smallest = i;
      const l = 2 * i + 1;
      const r = 2 * i + 2;
      if (l < n && this.heap[l].val < this.heap[smallest].val) smallest = l;
      if (r < n && this.heap[r].val < this.heap[smallest].val) smallest = r;
      if (smallest !== i) {
        [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
        i = smallest;
      } else break;
    }
  }
}

function mergeKLists(lists: Array<ListNode | null>): ListNode | null {
  const heap = new MinHeap();
  for (const node of lists) {
    if (node) heap.push(node);
  }

  const dummy = new ListNode(0);
  let tail = dummy;

  while (heap.size() > 0) {
    const node = heap.pop()!; // smallest current node
    tail.next = node;        // attach existing node
    tail = tail.next;
    if (node.next) heap.push(node.next);
    // optional: disconnect tail.next to avoid accidental long chains if reused
    tail.next = null;
  }

  return dummy.next;
}

```

Use the Boyer–Moore Voting Algorithm: scan the array once while maintaining a current candidate and a count, incrementing for the candidate and decrementing for others, and the final candidate is the majority.

```typescript
function majorityElement(nums: number[]): number {
  let candidate = nums[0];
  let count = 0;

  for (const num of nums) {
    if (count === 0) {
      candidate = num;
    }
    count += (num === candidate) ? 1 : -1;
  }

  return candidate;
}

// Example
console.log(majorityElement([3, 2, 3])); // 3
