Use a max-heap keyed by (priority, taskId) and a hash map taskInfo mapping taskId -> (userId, priority); on add/edit push a new heap entry and update the map, on rmv delete from the map, and on execTop pop until you find a heap entry that matches the current map entry (lazy deletion).

```typescript
class MaxHeapEntry { priority: number; taskId: number; constructor(priority: number, taskId: number) { this.priority = priority; this.taskId = taskId; } }

class MaxHeap {
  private data: MaxHeapEntry[] = [];

  size(): number { return this.data.length; }

  private compare(a: MaxHeapEntry, b: MaxHeapEntry): boolean {
    if (a.priority !== b.priority) return a.priority > b.priority;
    return a.taskId > b.taskId; // tie-break: larger taskId wins
  }

  push(e: MaxHeapEntry): void {
    this.data.push(e);
    this.siftUp(this.data.length - 1);
  }

  peek(): MaxHeapEntry | undefined {
    return this.data[0];
  }

  pop(): MaxHeapEntry | undefined {
    const n = this.data.length;
    if (n === 0) return undefined;
    if (n === 1) return this.data.pop();
    const top = this.data[0];
    this.data[0] = this.data.pop()!;
    this.siftDown(0);
    return top;
  }

  private siftUp(i: number): void {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.compare(this.data[i], this.data[p])) {
        [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
        i = p;
      } else break;
    }
  }

  private siftDown(i: number): void {
    const n = this.data.length;
    while (true) {
      const l = i * 2 + 1;
      const r = i * 2 + 2;
      let largest = i;
      if (l < n && this.compare(this.data[l], this.data[largest])) largest = l;
      if (r < n && this.compare(this.data[r], this.data[largest])) largest = r;
      if (largest === i) break;
      [this.data[i], this.data[largest]] = [this.data[largest], this.data[i]];
      i = largest;
    }
  }
}

class TaskManager {
  private heap = new MaxHeap();
  private taskInfo = new Map<number, { userId: number; priority: number }>();

  constructor(tasks: number[][]) {
    for (const t of tasks) {
      const [userId, taskId, priority] = t;
      this.add(userId, taskId, priority);
    }
  }

  add(userId: number, taskId: number, priority: number): void {
    this.taskInfo.set(taskId, { userId, priority });
    this.heap.push(new MaxHeapEntry(priority, taskId));
  }

  edit(taskId: number, newPriority: number): void {
    const info = this.taskInfo.get(taskId);
    if (!info) return; // per constraints taskId exists
    info.priority = newPriority;
    this.heap.push(new MaxHeapEntry(newPriority, taskId)); // lazy update
  }

  rmv(taskId: number): void {
    this.taskInfo.delete(taskId); // lazy removal; stale heap entries ignored later
  }

  execTop(): number {
    while (this.heap.size() > 0) {
      const top = this.heap.pop()!;
      const info = this.taskInfo.get(top.taskId);
      if (!info) continue; // removed
      if (info.priority !== top.priority) continue; // stale entry
      this.taskInfo.delete(top.taskId);
      return info.userId;
    }
    return -1;
  }
}

