// const tm = new TaskManager([[1,101,10],[2,102,20],[3,103,15]]);
// tm.add(4,104,5);
// tm.edit(102,8);
// console.log(tm.execTop()); // 3
// tm.rmv(101);
// tm.add(5,105,15);
