Build an undirected adjacency with a cost flag (0 if the stored direction matches the original edge, 1 if it would require reversal), compute reversals needed for an arbitrary root (say 0) by summing costs, then reroot using ans[child] = ans[parent] + (cost===0 ? 1 : -1) to get answers for every node.

```typescript
function minEdgeReversals(n: number, edges: number[][]): number[] {
  // adj[node] = array of [neighbor, cost]
  // cost === 0 means original edge is node -> neighbor (no reversal needed to go node->neighbor)
  // cost === 1 means original edge is neighbor -> node (would need reversal to go node->neighbor)
  const adj: Array<Array<[number, number]>> = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    adj[u].push([v, 0]); // original u -> v
    adj[v].push([u, 1]); // to go v -> u we'd need to reverse the original
  }

  const ans = new Array<number>(n).fill(0);

  // 1) compute reversals required when root = 0 by summing costs along a tree traversal
  let total = 0;
  const stack: [number, number][] = [[0, -1]]; // [node, parent]
  while (stack.length) {
    const [node, parent] = stack.pop()!;
    for (const [nei, cost] of adj[node]) {
      if (nei === parent) continue;
      total += cost; // if cost==1 this edge currently points toward node and needs reversal
      stack.push([nei, node]);
    }
  }
  ans[0] = total;

  // 2) reroot DP: propagate answers to children
  stack.length = 0;
  stack.push([0, -1]);
  while (stack.length) {
    const [node, parent] = stack.pop()!;
    for (const [nei, cost] of adj[node]) {
      if (nei === parent) continue;
      // if cost === 0 (original node->nei), moving root to nei makes this edge point toward the root and adds 1
      // if cost === 1 (original nei->node), moving root to nei removes the need to reverse this edge (-1)
      ans[nei] = ans[node] + (cost === 0 ? 1 : -1);
      stack.push([nei, node]);
    }
  }

  return ans;
}

// Example usage:
// console.log(minEdgeReversals(4, [[2,0],[2,1],[1,3]])); // [1,1,0,2]

