Sort the houses, precompute cost[i][j] as the minimum distance for houses i..j with one mailbox at the median, then use DP where dp[g][i] = min over t of dp[g-1][t] + cost[t][i-1].

```typescript
function minDistance(houses: number[], k: number): number {
  const n = houses.length;
  houses.sort((a, b) => a - b);

  // prefix sums for O(1) range sums
  const pref = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + houses[i];

  // cost[i][j] = min total distance to cover houses[i..j] with one mailbox at median
  const cost: number[][] = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      const mid = Math.floor((i + j) / 2);
      const leftSum = houses[mid] * (mid - i) - (pref[mid] - pref[i]);
      const rightSum = (pref[j + 1] - pref[mid + 1]) - houses[mid] * (j - mid);
      cost[i][j] = leftSum + rightSum;
    }
  }

  const INF = 1 << 30;
  // dp[g][i] = min cost to cover first i houses (houses[0..i-1]) with g mailboxes
  const dp: number[][] = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(INF));
  dp[0][0] = 0;

  for (let g = 1; g <= k; g++) {
    for (let i = g; i <= n; i++) {
      // t = number of houses covered by first g-1 mailboxes (at least g-1 to leave >=1 house per mailbox)
      for (let t = g - 1; t <= i - 1; t++) {
        dp[g][i] = Math.min(dp[g][i], dp[g - 1][t] + cost[t][i - 1]);
      }
    }
  }

  return dp[k][n];
}

// Example
// console.log(minDistance([1,4,8,10,20], 3)); // 5

