Sort the folder list lexicographically, then scan once keeping a folder only if it does not start with the last kept folder plus '/' (so sub-folders follow their parent and are skipped).

```typescript
function removeSubfolders(folder: string[]): string[] {
  // Sort so that any sub-folder appears immediately after its parent
  folder.sort();
  const result: string[] = [];

  for (const f of folder) {
    if (result.length === 0) {
      result.push(f);
      continue;
    }
    const last = result[result.length - 1];
    // If f starts with last + '/', it's a sub-folder and should be skipped
    if (!f.startsWith(last + '/')) {
      result.push(f);
    }
  }

  return result;
}

