type Person = { personId: number; lastName: string; firstName: string };
type Address = { addressId: number; personId: number; city: string; state: string };
type Result = { firstName: string; lastName: string; city: string | null; state: string | null };

function combineTables(persons: Person[], addresses: Address[]): Result[] {
  // Map addresses by personId for O(1) lookup
  const addrMap = new Map<number, Address>();
  for (const a of addresses) {
    if (!addrMap.has(a.personId)) addrMap.set(a.personId, a); // keep first address if multiples
  }

  // For each person, lookup address (left join semantics)
  return persons.map(p => {
    const a = addrMap.get(p.personId) || null;
    return {
      firstName: p.firstName,
      lastName: p.lastName,
      city: a ? a.city : null,
      state: a ? a.state : null
    };
  });
}

