Use a two-pointer sliding window over the sorted fruit positions, maintain the window sum, and for each window check if the minimal steps to cover its endpoints (min(|s-left|, |s-right|) + (right-left)) is <= k, shrinking the left pointer when it isn't.

```typescript
function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
  const n = fruits.length;
  let left = 0;
  let sum = 0;
  let ans = 0;

  for (let right = 0; right < n; right++) {
    // include fruits at right
    sum += fruits[right][1];

    // shrink from left while the window [left..right] is not reachable within k steps
    while (left <= right) {
      const L = fruits[left][0];
      const R = fruits[right][0];
      const span = R - L; // distance between endpoints
      // minimal steps to visit entire interval [L,R] starting from startPos:
      const steps = Math.min(Math.abs(startPos - L) + span, Math.abs(startPos - R) + span);
      if (steps <= k) break;
      // not reachable, drop left
      sum -= fruits[left][1];
      left++;
    }

    // current window is reachable, update answer
    ans = Math.max(ans, sum);
  }

  return ans;
}

// Example usage:
// console.log(maxTotalFruits([[2,8],[6,3],[8,6]], 5, 4)); // 9
