Use two pointers (read i for the start of each group and write res for output): scan groups left-to-right, write the character and, if count>1, write the decimal digits of the count into chars, advancing res accordingly.

```typescript
function compress(chars: string[]): number {
    const n = chars.length;
    let i = 0; // read pointer at start of current group
    let res = 0; // write pointer for compressed output

    while (i < n) {
        const ch = chars[i];
        let j = i;
        while (j < n && chars[j] === ch) j++;
        const count = j - i;

        // write the character
        chars[res++] = ch;

        // if count > 1, write its digits
        if (count > 1) {
            const s = String(count);
            for (let k = 0; k < s.length; k++) {
                chars[res++] = s.charAt(k);
            }
        }

        // move to next group
        i = j;
    }

    return res;
}

