Greedily simulate exchanges by tracking empties: repeatedly convert empties to new full bottles via integer division, add them to the total, and carry the remainder empties until no more exchanges are possible.

```typescript
function maxWaterBottles(numBottles: number, numExchange: number): number {
  let total = numBottles;
  let empties = numBottles;

  while (empties >= numExchange) {
    const newFull = Math.floor(empties / numExchange);
    total += newFull;
    empties = newFull + (empties % numExchange);
  }

  return total;
}

