Use a max-heap to keep the n smallest sums for each prefix and a min-heap to keep the n largest sums for each suffix, then scan the split positions to minimize leftSum - rightSum.

```typescript
class Heap<T> {
  private data: T[] = [];
  constructor(private cmp: (a: T, b: T) => boolean) {}
  size(): number { return this.data.length; }
  peek(): T | undefined { return this.data[0]; }
  push(val: T): void {
    this.data.push(val);
    this.siftUp(this.data.length - 1);
  }
  pop(): T | undefined {
    if (this.data.length === 0) return undefined;
    const top = this.data[0];
    const last = this.data.pop()!;
    if (this.data.length > 0) {
      this.data[0] = last;
      this.siftDown(0);
    }
    return top;
  }
  private siftUp(i: number) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.cmp(this.data[i], this.data[p])) {
        [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
        i = p;
      } else break;
    }
  }
  private siftDown(i: number) {
    const n = this.data.length;
    while (true) {
      let l = i * 2 + 1;
      if (l >= n) break;
      let r = l + 1;
      let best = l;
      if (r < n && this.cmp(this.data[r], this.data[l])) best = r;
      if (this.cmp(this.data[best], this.data[i])) {
        [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
        i = best;
      } else break;
    }
  }
}

function minDifference(nums: number[]): number {
  const total = nums.length;
  const n = Math.floor(total / 3);

  // left[i] = sum of n smallest elements in nums[0..i]
  const left = new Array<number>(total).fill(0);
  const maxHeap = new Heap<number>((a, b) => a > b); // max-heap
  let sum = 0;
  for (let i = 0; i < n; i++) { maxHeap.push(nums[i]); sum += nums[i]; }
  left[n - 1] = sum;
  for (let i = n; i < 2 * n; i++) {
    maxHeap.push(nums[i]);
    sum += nums[i];
    if (maxHeap.size() > n) {
      const removed = maxHeap.pop()!;
      sum -= removed;
    }
    left[i] = sum;
  }

  // right[i] = sum of n largest elements in nums[i..total-1]
  const right = new Array<number>(total).fill(0);
  const minHeap = new Heap<number>((a, b) => a < b); // min-heap
  sum = 0;
  for (let i = 2 * n; i < total; i++) { minHeap.push(nums[i]); sum += nums[i]; }
  right[2 * n] = sum;
  for (let i = 2 * n - 1; i >= n; i--) {
    minHeap.push(nums[i]);
    sum += nums[i];
    if (minHeap.size() > n) {
      const removed = minHeap.pop()!;
      sum -= removed;
    }
    right[i] = sum;
  }

  let ans = Infinity;
  // split between i and i+1, where i in [n-1, 2n-1]
  for (let i = n - 1; i < 2 * n; i++) {
    ans = Math.min(ans, left[i] - right[i + 1]);
  }
  return ans;
}

// Example usage:
// console.log(minDifference([7,9,5,8,1,3])); // 1

