Binary search the minimum time T and for each T check feasibility by verifying each drone has at least di available hours (T - floor(T/ri)) and that the number of hours with at least one drone available (T - floor(T/lcm(r1,r2))) is >= d1 + d2.

```typescript
function minTime(d: number[], r: number[]): number {
  const [d1, d2] = d;
  const [r1, r2] = r;

  function gcd(a: number, b: number): number {
    while (b !== 0) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  const g = gcd(r1, r2);
  const lcm = (r1 / g) * r2; // safe within Number for given constraints
  const totalNeeded = d1 + d2;

  function feasible(T: number): boolean {
    const avail1 = T - Math.floor(T / r1);
    const avail2 = T - Math.floor(T / r2);
    if (avail1 < d1 || avail2 < d2) return false;
    const hoursAtLeastOne = T - Math.floor(T / lcm);
    return hoursAtLeastOne >= totalNeeded;
  }

  // Binary search with exponential upper bound growth
  let left = 0;
  let right = 1;
  while (!feasible(right)) {
    right *= 2;
  }
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (feasible(mid)) right = mid;
    else left = mid + 1;
  }
  return left;
}

// Example usage:
// console.log(minTime([3,1], [2,3])); // 5

```

Generate a small set of candidate palindromes by mirroring the left half of n and the left half +/-1, plus the edge cases 9...9 and 1 followed by zeros and 1, then choose the candidate (not equal to n) with the smallest absolute difference (tie -> smaller).

```typescript
function nearestPalindromic(n: string): string {
  const len = n.length;
  const candidates = new Set<string>();

  // Edge cases: 10...01 and 9...9 (len-1 times)
  candidates.add('1' + '0'.repeat(len - 1) + '1');
  candidates.add(len === 1 ? '0' : '9'.repeat(len - 1));

  const prefixLen = Math.ceil(len / 2);
  const prefix = n.slice(0, prefixLen);

  function rev(s: string) { return s.split('').reverse().join(''); }
  function makePalindrome(left: string) {
    if (len % 2 === 0) return left + rev(left);
    return left + rev(left.slice(0, -1));
  }

  for (const d of [0, 1, -1]) {
    const num = BigInt(prefix) + BigInt(d);
    if (num < 0n) continue; // safety, though shouldn't happen for valid input
    const left = num.toString();
    candidates.add(makePalindrome(left));
  }

  candidates.delete(n); // exclude the number itself

  // choose the closest; on tie choose the smaller numeric value
  const orig = BigInt(n);
  let best: string | null = null;
  let bestDiff: bigint | null = null;

  for (const cand of candidates) {
    if (cand.length > 1 && cand[0] === '0') continue; // skip leading-zero palindromes
    const cVal = BigInt(cand);
    const diff = cVal > orig ? cVal - orig : orig - cVal;
    if (
      best === null ||
      (bestDiff !== null && diff < bestDiff) ||
      (bestDiff !== null && diff === bestDiff && cVal < BigInt(best))
    ) {
      best = cand;
      bestDiff = diff;
    }
  }

  return best as string;
}

// Example usage:
// console.log(nearestPalindromic("123")); // "121"
// console.log(nearestPalindromic("1"));   // "0"
