Compute net balances, collect non-zero balances into a list, then use DFS/backtracking to settle the current person with opposite-sign balances while pruning duplicate/zero cases to minimize the number of transactions.

```typescript
const minTransfers = (transactions: number[][]): number => {
  // Build net balance per person
  const balanceMap = new Map<number, number>();
  for (const [from, to, amount] of transactions) {
    balanceMap.set(from, (balanceMap.get(from) || 0) - amount);
    balanceMap.set(to, (balanceMap.get(to) || 0) + amount);
  }

  // Collect non-zero balances
  const balances: number[] = [];
  for (const v of balanceMap.values()) {
    if (v !== 0) balances.push(v);
  }

  const n = balances.length;
  // DFS: settle balances[start] by pairing with later opposite-sign balances
  const dfs = (start: number): number => {
    // skip already-settled people
    while (start < n && balances[start] === 0) start++;
    if (start === n) return 0;

    let res = Infinity;
    const seen = new Set<number>(); // prune equal values to avoid duplicate work

    for (let i = start + 1; i < n; i++) {
      if (balances[i] * balances[start] < 0 && !seen.has(balances[i])) {
        seen.add(balances[i]);
        // settle start with i
        balances[i] += balances[start];
        res = Math.min(res, 1 + dfs(start + 1));
        // backtrack
        balances[i] -= balances[start];
        // if we exactly canceled balances[i], no need to try other i (pruning)
        if (balances[i] + balances[start] === 0) break;
      }
    }

    return res === Infinity ? 0 : res;
  };

  return dfs(0);
};
```

Precompute the (small) list of all numerically balanced numbers once, then binary-search that sorted list to find the smallest value strictly greater than n.

```typescript
function nextNumericallyBalancedNumber(n: number): number {
  // Cached precomputed list of numerically balanced numbers
  const MAX = 1224444; // sufficient upper bound per problem analysis
  const cacheKey = "__BALANCED_LIST__" as any;
  // simple global cache via (globalThis as any) to avoid recomputing across calls
  if (!(globalThis as any)[cacheKey]) {
    const isBalanced = (num: number): boolean => {
      const s = String(num);
      const cnt = new Array(10).fill(0);
      for (let i = 0; i < s.length; i++) {
        const d = s.charCodeAt(i) - 48;
        cnt[d]++;
      }
      if (cnt[0] > 0) return false; // digit 0 cannot appear
      for (let d = 1; d <= 9; d++) {
        if (cnt[d] > 0 && cnt[d] !== d) return false;
      }
      return true;
    };

    const list: number[] = [];
    for (let i = 1; i <= MAX; i++) {
      if (isBalanced(i)) list.push(i);
    }
    (globalThis as any)[cacheKey] = list;
  }

  const list: number[] = (globalThis as any)[cacheKey];
  // binary search for first element > n
  let l = 0, r = list.length - 1, ans = -1;
  while (l <= r) {
    const mid = (l + r) >> 1;
    if (list[mid] > n) {
      ans = list[mid];
      r = mid - 1;
    } else {
      l = mid + 1;
    }
  }
  return ans;
}

// Example
// console.log(nextNumericallyBalancedNumber(1000)); // 1333
