Enumerate k from 1..60 and check if x = num1 - k*num2 satisfies x >= k and popcount(x) <= k; the first valid k is the answer (otherwise -1).

```typescript
function minimumOperations(num1: number, num2: number): number {
  // We only need to try up to 60 operations (i ranges 0..60)
  for (let k = 1; k <= 60; k++) {
    const x = num1 - k * num2;
    if (x < k) continue; // even k copies of 2^0 can't reach x

    // count number of 1-bits in x without using bitwise ops that coerce to 32-bit
    let ones = 0;
    let y = x;
    while (y > 0 && ones <= k) {
      ones += y % 2;
      y = Math.floor(y / 2);
    }

    if (ones <= k && k <= x) return k;
  }
  return -1;
}

