Build a directed graph of letter precedence by comparing adjacent words (first differing characters), compute indegrees, and run Kahn's topological sort (BFS) to produce a valid ordering or detect a cycle/prefix invalidity.

```typescript
function alienOrder(words: string[]): string {
  const adj = new Map<string, Set<string>>();
  const indegree = new Map<string, number>();

  // Initialize nodes for every unique character
  for (const w of words) {
    for (const ch of w) {
      if (!adj.has(ch)) adj.set(ch, new Set());
      if (!indegree.has(ch)) indegree.set(ch, 0);
    }
  }

  // Build edges by comparing adjacent words
  for (let i = 0; i < words.length - 1; i++) {
    const a = words[i];
    const b = words[i + 1];
    const len = Math.min(a.length, b.length);
    let found = false;
    for (let j = 0; j < len; j++) {
      const ca = a[j];
      const cb = b[j];
      if (ca !== cb) {
        // add edge ca -> cb if not already added
        const set = adj.get(ca)!;
        if (!set.has(cb)) {
          set.add(cb);
          indegree.set(cb, (indegree.get(cb) ?? 0) + 1);
        }
        found = true;
        break;
      }
    }
    // If no difference and a is longer than b, invalid (prefix case)
    if (!found && a.length > b.length) return "";
  }

  // Kahn's algorithm
  const q: string[] = [];
  for (const [ch, deg] of indegree) {
    if (deg === 0) q.push(ch);
  }

  let idx = 0;
  const res: string[] = [];
  while (idx < q.length) {
    const node = q[idx++];
    res.push(node);
    for (const nei of adj.get(node) ?? []) {
      indegree.set(nei, indegree.get(nei)! - 1);
      if (indegree.get(nei)! === 0) q.push(nei);
    }
  }

  // If not all chars are in result, there was a cycle
  if (res.length !== indegree.size) return "";
  return res.join('');
}

// Example usage:
// console.log(alienOrder(["wrt","wrf","er","ett","rftt"])); // "wertf"
```

Binary search the achievable running time t and check feasibility by summing min(battery, t) across all batteries to see if it reaches t * n.

```typescript
function maxRunTime(n: number, batteries: number[]): number {
  // total power cap gives an upper bound for running time
  let total = 0;
  for (const b of batteries) total += b;

  // search space: 0..floor(total / n)
  let left = 0;
  let right = Math.floor(total / n);
  let best = 0;

  const canRun = (t: number): boolean => {
    // check if we can gather at least t * n minutes
    let acc = 0;
    for (const b of batteries) {
      acc += Math.min(b, t);
      if (acc >= t * n) return true; // early exit
    }
    return acc >= t * n;
  };

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (canRun(mid)) {
      best = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return best;
}

// Example usage:
// console.log(maxRunTime(2, [3,3,3])); // 4
