Use DFS-based backtracking from each cell, marking visited cells in-place and restoring them after exploring each path to check whether the word can be formed.

```typescript
function exist(board: string[][], word: string): boolean {
  const m = board.length;
  const n = board[0].length;
  const L = word.length;
  const dirs: number[][] = [[-1,0],[0,1],[1,0],[0,-1]];

  function backtrack(r: number, c: number, i: number): boolean {
    if (i === L) return true; // matched all characters
    if (r < 0 || r >= m || c < 0 || c >= n) return false;
    if (board[r][c] !== word[i]) return false;

    const tmp = board[r][c];
    board[r][c] = '#'; // mark visited

    for (const [dr, dc] of dirs) {
      if (backtrack(r + dr, c + dc, i + 1)) {
        board[r][c] = tmp; // restore before returning
        return true;
      }
    }

    board[r][c] = tmp; // restore
    return false;
  }

  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (backtrack(r, c, 0)) return true;
    }
  }

  return false;
}

