Use a max-heap (priority queue) keyed by remaining frequency and repeatedly take the two most frequent different characters, append them, decrement counts, and push back if still remaining.

```typescript
type Pair = { cnt: number; ch: string };

class MaxHeap {
  private heap: Pair[] = [];

  size(): number {
    return this.heap.length;
  }

  push(item: Pair): void {
    this.heap.push(item);
    this.siftUp(this.heap.length - 1);
  }

  pop(): Pair | undefined {
    if (this.heap.length === 0) return undefined;
    const top = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.siftDown(0);
    }
    return top;
  }

  private siftUp(idx: number): void {
    while (idx > 0) {
      const parent = (idx - 1) >> 1;
      if (this.heap[parent].cnt >= this.heap[idx].cnt) break;
      [this.heap[parent], this.heap[idx]] = [this.heap[idx], this.heap[parent]];
      idx = parent;
    }
  }

  private siftDown(idx: number): void {
    const n = this.heap.length;
    while (true) {
      const left = idx * 2 + 1;
      const right = left + 1;
      let largest = idx;
      if (left < n && this.heap[left].cnt > this.heap[largest].cnt) largest = left;
      if (right < n && this.heap[right].cnt > this.heap[largest].cnt) largest = right;
      if (largest === idx) break;
      [this.heap[largest], this.heap[idx]] = [this.heap[idx], this.heap[largest]];
      idx = largest;
    }
  }
}

function reorganizeString(s: string): string {
  const freq = new Array(26).fill(0);
  for (const ch of s) freq[ch.charCodeAt(0) - 97]++;

  const heap = new MaxHeap();
  for (let i = 0; i < 26; i++) {
    if (freq[i] > 0) heap.push({ cnt: freq[i], ch: String.fromCharCode(97 + i) });
  }

  let res = '';

  // Take two most frequent different chars each step
  while (heap.size() > 1) {
    const p1 = heap.pop()!;
    const p2 = heap.pop()!;
    res += p1.ch;
    res += p2.ch;
    p1.cnt--;
    p2.cnt--;
    if (p1.cnt > 0) heap.push(p1);
    if (p2.cnt > 0) heap.push(p2);
  }

  if (heap.size() === 1) {
    const last = heap.pop()!;
    // If more than one of the same char remain it's impossible
    if (last.cnt > 1) return '';
    // If last char equals the current tail, impossible
    if (res.length > 0 && res[res.length - 1] === last.ch) return '';
    res += last.ch;
  }

  return res;
}

// Example
console.log(reorganizeString('aab')); // e.g. "aba"
