For each k-length window, count occurrences with a hash map, sort entries by count desc then value desc, and sum the top x (or all if fewer) element contributions.

```typescript
function xSumAllKLongSubarrays(nums: number[], k: number, x: number): number[] {
  const n = nums.length;
  const ans: number[] = [];

  for (let i = 0; i <= n - k; i++) {
    const cnt = new Map<number, number>();
    for (let j = i; j < i + k; j++) {
      cnt.set(nums[j], (cnt.get(nums[j]) ?? 0) + 1);
    }

    const entries = Array.from(cnt.entries()); // [value, count]
    entries.sort((a, b) => {
      if (b[1] !== a[1]) return b[1] - a[1]; // higher count first
      return b[0] - a[0]; // tie-breaker: larger value first
    });

    let sum = 0;
    const take = Math.min(x, entries.length);
    for (let t = 0; t < take; t++) {
      sum += entries[t][0] * entries[t][1];
    }
    ans.push(sum);
  }

  return ans;
}

// Example usage:
// console.log(xSumAllKLongSubarrays([1,1,2,2,3,4,2,3], 6, 2)); // [6,10,12]

