Perform DFS with backtracking using the robot API: mark and clean visited cells, try all 4 directions (rotating the robot), move into unvisited open cells recursively, and on return use a 180° move to go back to the previous cell.

```typescript
interface Robot {
  move(): boolean; // returns true if next cell is open and robot moves into the cell
  turnLeft(): void;
  turnRight(): void;
  clean(): void;
}

function cleanRoom(robot: Robot): void {
  const visited = new Set<string>();
  // directions: up, right, down, left
  const dirs = [[-1, 0], [0, 1], [1, 0], [0, -1]];

  function key(x: number, y: number) {
    return `${x}#${y}`;
  }

  function goBack() {
    // turn around, move one step, turn around to restore original orientation
    robot.turnRight();
    robot.turnRight();
    robot.move();
    robot.turnRight();
    robot.turnRight();
  }

  function dfs(x: number, y: number, dir: number) {
    visited.add(key(x, y));
    robot.clean();

    for (let i = 0; i < 4; i++) {
      const nd = (dir + i) % 4;
      const nx = x + dirs[nd][0];
      const ny = y + dirs[nd][1];
      if (!visited.has(key(nx, ny))) {
        // Try to move into the next cell in nd direction
        if (robot.move()) {
          // moved into (nx, ny) and robot faces nd
          dfs(nx, ny, nd);
          // backtrack to (x, y) and restore facing nd
          goBack();
        }
      }
      // turn the robot right to try the next direction
      robot.turnRight();
    }
  }

  // start from (0,0) in our coordinate system with initial facing 'up' (dir = 0)
  dfs(0, 0, 0);
}

