Compute the candidate reflection line x = (minX + maxX)/2 and verify for every point (x,y) that its mirrored point (minX+maxX-x, y) exists using a hash set of point strings.

```typescript
function isReflected(points: number[][]): boolean {
  if (points.length <= 1) return true;

  let minX = Infinity;
  let maxX = -Infinity;
  const set = new Set<string>();

  for (const p of points) {
    const x = p[0], y = p[1];
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    set.add(`${x}#${y}`);
  }

  const sum = minX + maxX; // equals 2*mid
  for (const p of points) {
    const x = p[0], y = p[1];
    const mirrorKey = `${sum - x}#${y}`;
    if (!set.has(mirrorKey)) return false;
  }
  return true;
}

// Example usage:
// console.log(isReflected([[1,1],[-1,1]])); // true
// console.log(isReflected([[1,1],[-1,-1]])); // false
