Sort nums, enumerate every possible target value between min(nums) and max(nums), use binary search to find how many elements lie within [target-k, target+k], and combine that with existing occurrences of target (capped by numOperations) to get the best achievable frequency.

```typescript
function maxFrequencyAfterOperations(nums: number[], k: number, numOperations: number): number {
  if (nums.length === 0) return 0;
  // Sort a copy of nums
  nums = nums.slice().sort((a, b) => a - b);
  const n = nums.length;
  // Count occurrences of each value
  const count = new Map<number, number>();
  for (const x of nums) count.set(x, (count.get(x) || 0) + 1);

  const minNum = nums[0];
  const maxNum = nums[n - 1];
  let ans = 1;

  function lowerBound(arr: number[], target: number): number {
    let l = 0, r = arr.length;
    while (l < r) {
      const mid = (l + r) >>> 1;
      if (arr[mid] < target) l = mid + 1;
      else r = mid;
    }
    return l; // first index with arr[idx] >= target
  }

  function upperBoundIndex(arr: number[], target: number): number {
    // returns last index with arr[idx] <= target, or -1 if none
    let l = 0, r = arr.length;
    while (l < r) {
      const mid = (l + r) >>> 1;
      if (arr[mid] <= target) l = mid + 1;
      else r = mid;
    }
    return l - 1;
  }

  for (let m = minNum; m <= maxNum; ++m) {
    const l = lowerBound(nums, m - k);
    const r = upperBoundIndex(nums, m + k);
    if (l > r) continue; // no candidates that can be adjusted to m
    const len = r - l + 1; // number of elements within [m-k, m+k]
    const cnt = count.get(m) || 0; // existing occurrences of m
    // We can use up to numOperations extra elements (plus existing cnt), but not more than len
    const f = Math.min(len, numOperations + cnt);
    if (f > ans) ans = f;
    if (ans === n) return ans; // early exit if we reached maximum possible
  }

  return ans;
}

// Example usage:
// console.log(maxFrequencyAfterOperations([1,4,5], 1, 2)); // 2
```

Convert numbers to strings and sort them with a custom comparator that orders a before b when a+b > b+a, then concatenate (return "0" if the result starts with '0').

```typescript
export function largestNumber(nums: number[]): string {
  // Convert numbers to strings
  const strs = nums.map(String);

  // Sort with custom comparator: place a before b if a+b > b+a
  strs.sort((a, b) => {
    const ab = a + b;
    const ba = b + a;
    if (ab > ba) return -1; // a should come before b
    if (ab < ba) return 1;  // b should come before a
    return 0;
  });

  // If the highest value is "0", the whole number is 0
  if (strs[0] === "0") return "0";

  // Join and return
  return strs.join("");
}

