Maintain a monotonic decreasing deque of indices (keeping only 'useful' candidates) so each index is pushed and popped at most once, yielding O(n) time.

```typescript
function maxSlidingWindow(nums: number[], k: number): number[] {
  const n = nums.length;
  const res: number[] = [];
  if (n === 0 || k === 0) return res;
  if (k === 1) return nums.slice();

  // Deque implemented as array of indices with a head pointer to avoid O(n) shift.
  const dq: number[] = [];
  let head = 0;

  for (let i = 0; i < n; i++) {
    // Remove smaller elements from the back (they can't be max while nums[i] is in window)
    while (dq.length - head > 0 && nums[i] >= nums[dq[dq.length - 1]]) {
      dq.pop();
    }

    // Add current index
    dq.push(i);

    // Remove indices that are out of the current window from the front
    if (dq.length - head > 0 && dq[head] <= i - k) {
      head++;
    }

    // Periodically compact the array to prevent unbounded growth
    if (head > 0 && head * 2 >= dq.length) {
      dq.splice(0, head);
      head = 0;
    }

    // Once we've processed k elements, record the current max
    if (i >= k - 1) {
      res.push(nums[dq[head]]);
    }
  }

  return res;
}
