Convert n to m = ceil(n/25) servings and use memoized recursion for dp[i][j] with base cases (i<=0,j<=0 => 0.5; i<=0 =>1; j<=0 =>0), and return 1 early when m is large (m >= 200) to satisfy the 1e-5 tolerance.

```typescript
function soupServings(n: number): number {
  // Convert to servings of 25ml
  const m = Math.ceil(n / 25);
  // For large m the probability is effectively 1 within 1e-5 (empirically m >= 200)
  if (m >= 200) return 1.0;

  const memo: number[][] = Array.from({ length: m + 1 }, () => Array(m + 1).fill(-1));

  function dp(i: number, j: number): number {
    if (i <= 0 && j <= 0) return 0.5;
    if (i <= 0) return 1.0;
    if (j <= 0) return 0.0;
    if (memo[i][j] >= 0) return memo[i][j];

    const res = 0.25 * (
      dp(i - 4, j) +
      dp(i - 3, j - 1) +
      dp(i - 2, j - 2) +
      dp(i - 1, j - 3)
    );

    memo[i][j] = res;
    return res;
  }

  return dp(m, m);
}

// Example
console.log(soupServings(50)); // ~0.625
