Use dynamic programming with dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + skill[i]*mana[j], optimized to a 1D dp over wizards (O(nm) time, O(n) space).

```typescript
function minTimeToBrew(skill: number[], mana: number[]): number {
  const n = skill.length;
  const m = mana.length;
  if (n === 0 || m === 0) return 0;

  // dp[i] will hold the completion time of the current potion at wizard i
  const dp: number[] = new Array(n).fill(0);

  // Initialize for the first potion (j = 0)
  dp[0] = skill[0] * mana[0];
  for (let i = 1; i < n; i++) {
    dp[i] = dp[i - 1] + skill[i] * mana[0];
  }

  // Process subsequent potions j = 1..m-1
  for (let j = 1; j < m; j++) {
    // Wizard 0 must process potions sequentially
    dp[0] += skill[0] * mana[j];
    for (let i = 1; i < n; i++) {
      // max of: wizard i finished previous potion (dp[i]) or wizard i-1 finished current potion (dp[i-1])
      dp[i] = Math.max(dp[i], dp[i - 1]) + skill[i] * mana[j];
    }
  }

  return dp[n - 1];
}

// Example
console.log(minTimeToBrew([1,5,2,4], [5,1,4,2])); // 110
