Use prefix sums: for each index i with nums[i]==0, let left = sum(nums[0..i-1]) and right = sum(nums[i+1..n-1]); the right-start is valid iff right==left or right==left+1, and symmetrically for left-start, so count directions satisfying these conditions in O(n).

```typescript
function countValidSelections(nums: number[]): number {
  const n = nums.length;
  const total = nums.reduce((s, v) => s + v, 0);
  let leftSum = 0;
  let count = 0;

  for (let i = 0; i < n; i++) {
    if (nums[i] === 0) {
      const rightSum = total - leftSum; // nums[i] is 0, so rightSum = total - leftSum - nums[i] === total - leftSum
      // starting direction: right
      if (rightSum === leftSum || rightSum === leftSum + 1) count++;
      // starting direction: left
      if (leftSum === rightSum || leftSum === rightSum + 1) count++;
    }
    leftSum += nums[i];
  }

  return count;
}

// Example
// console.log(countValidSelections([1,0,2,0,3])); // 2
// console.log(countValidSelections([2,3,4,0,4,1,0])); // 0
