Count frequencies with a hash map, then maintain a min-heap of size k keyed by frequency to keep the top k frequent elements (pop the smallest frequency when size > k).

```typescript
class MinHeap<T> {
  private data: T[] = [];
  private cmp: (a: T, b: T) => number;

  constructor(cmp: (a: T, b: T) => number) {
    this.cmp = cmp;
  }

  size(): number {
    return this.data.length;
  }

  peek(): T | undefined {
    return this.data[0];
  }

  push(value: T): void {
    this.data.push(value);
    this.bubbleUp(this.data.length - 1);
  }

  pop(): T | undefined {
    const n = this.data.length;
    if (n === 0) return undefined;
    this.swap(0, n - 1);
    const popped = this.data.pop();
    this.bubbleDown(0);
    return popped;
  }

  private parent(i: number) { return Math.floor((i - 1) / 2); }
  private left(i: number) { return i * 2 + 1; }
  private right(i: number) { return i * 2 + 2; }

  private swap(i: number, j: number) {
    const t = this.data[i];
    this.data[i] = this.data[j];
    this.data[j] = t;
  }

  private bubbleUp(idx: number) {
    while (idx > 0) {
      const p = this.parent(idx);
      if (this.cmp(this.data[idx], this.data[p]) < 0) {
        this.swap(idx, p);
        idx = p;
      } else break;
    }
  }

  private bubbleDown(idx: number) {
    const n = this.data.length;
    while (true) {
      const l = this.left(idx);
      const r = this.right(idx);
      let smallest = idx;
      if (l < n && this.cmp(this.data[l], this.data[smallest]) < 0) smallest = l;
      if (r < n && this.cmp(this.data[r], this.data[smallest]) < 0) smallest = r;
      if (smallest !== idx) {
        this.swap(idx, smallest);
        idx = smallest;
      } else break;
    }
  }
}

function topKFrequent(nums: number[], k: number): number[] {
  const freq = new Map<number, number>();
  for (const x of nums) freq.set(x, (freq.get(x) || 0) + 1);

  // Min-heap of pairs [num, count], ordered by count
  type Pair = [number, number];
  const heap = new MinHeap<Pair>((a, b) => a[1] - b[1]);

  for (const [num, count] of freq.entries()) {
    heap.push([num, count]);
    if (heap.size() > k) heap.pop();
  }

  const res: number[] = [];
  while (heap.size() > 0) {
    const p = heap.pop();
    if (p) res.push(p[0]);
  }

  // result currently in ascending frequency order; any order is allowed
  return res;
}

// Example usage:
// console.log(topKFrequent([1,1,1,2,2,3], 2)); // [1,2] (order may vary)
