Collect all users who are in friend pairs that cannot currently communicate, count for each language how many of those users already know it, and teach the language that maximizes that count (answer = number of such users - maxCount).

```typescript
function minimumTeachings(n: number, languages: number[][], friendships: number[][]): number {
  // Build per-user language sets
  const userLangSets = languages.map(arr => new Set<number>(arr));

  // Collect users involved in non-communicating friendships
  const badUsers = new Set<number>(); // store 0-based user indices
  for (const [u1, u2] of friendships) {
    const a = userLangSets[u1 - 1];
    const b = userLangSets[u2 - 1];
    let canCommunicate = false;
    // iterate the smaller set to check intersection faster
    if (a.size < b.size) {
      for (const lang of a) {
        if (b.has(lang)) { canCommunicate = true; break; }
      }
    } else {
      for (const lang of b) {
        if (a.has(lang)) { canCommunicate = true; break; }
      }
    }
    if (!canCommunicate) {
      badUsers.add(u1 - 1);
      badUsers.add(u2 - 1);
    }
  }

  if (badUsers.size === 0) return 0;

  // Count how many of the badUsers already know each language
  const count = new Array<number>(n + 1).fill(0); // 1-based language ids
  for (const userIdx of badUsers) {
    for (const lang of languages[userIdx]) {
      count[lang]++;
    }
  }

  let maxKnown = 0;
  for (let lang = 1; lang <= n; lang++) {
    if (count[lang] > maxKnown) maxKnown = count[lang];
  }

  // Teach the chosen language to all bad users who don't already know it
  return badUsers.size - maxKnown;
}

// Example usage:
// console.log(minimumTeachings(2, [[1],[2],[1,2]], [[1,2],[1,3],[2,3]])); // 1
