Use a regular stack plus a max-heap with unique IDs and lazy deletion (a removed-ID set) so top is O(1) and push/pop/popMax/peekMax are O(log n) amortized.

```typescript
class MaxHeap<T> {
  private data: T[] = [];
  constructor(private cmp: (a: T, b: T) => number) {}
  size() { return this.data.length; }
  peek() { return this.data[0]; }
  push(x: T) {
    this.data.push(x);
    this.siftUp(this.data.length - 1);
  }
  pop() {
    const n = this.data.length;
    if (!n) return undefined;
    this.swap(0, n - 1);
    const top = this.data.pop();
    this.siftDown(0);
    return top;
  }
  private siftUp(i: number) {
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (this.cmp(this.data[i], this.data[p]) <= 0) break;
      this.swap(i, p);
      i = p;
    }
  }
  private siftDown(i: number) {
    const n = this.data.length;
    while (true) {
      let l = 2 * i + 1;
      let r = 2 * i + 2;
      let best = i;
      if (l < n && this.cmp(this.data[l], this.data[best]) > 0) best = l;
      if (r < n && this.cmp(this.data[r], this.data[best]) > 0) best = r;
      if (best === i) break;
      this.swap(i, best);
      i = best;
    }
  }
  private swap(i: number, j: number) {
    const t = this.data[i];
    this.data[i] = this.data[j];
    this.data[j] = t;
  }
}

type Node = { val: number; id: number };

class MaxStack {
  private stack: Node[] = [];
  private heap: MaxHeap<Node>;
  private removed = new Set<number>();
  private nextId = 0;

  constructor() {
    // comparator: larger val first, if tie prefer larger id (more recent)
    this.heap = new MaxHeap<Node>((a, b) => {
      if (a.val !== b.val) return a.val - b.val;
      return a.id - b.id;
    });
  }

  push(x: number): void {
    const node = { val: x, id: this.nextId++ };
    this.stack.push(node);
    this.heap.push(node);
  }

  private cleanStackTop() {
    while (this.stack.length && this.removed.has(this.stack[this.stack.length - 1].id)) {
      this.stack.pop();
    }
  }

  private cleanHeapTop() {
    while (this.heap.size() && this.removed.has(this.heap.peek().id)) {
      this.heap.pop();
    }
  }

  pop(): number {
    this.cleanStackTop();
    const node = this.stack.pop();
    // per constraints, there is always an element when pop is called
    this.removed.add(node.id);
    return node.val;
  }

  top(): number {
    this.cleanStackTop();
    return this.stack[this.stack.length - 1].val;
  }

  peekMax(): number {
    this.cleanHeapTop();
    return this.heap.peek().val;
  }

  popMax(): number {
    this.cleanHeapTop();
    const node = this.heap.pop();
    this.removed.add(node.id);
    return node.val;
  }
}

