Sum the main diagonal (fixed path for the (0,0) child), then run an O(n^2) rolling-array DP once on the upper triangular region and once on the transposed matrix (lower region) to get the other two children, subtracting the final cell once to avoid double-counting.

```typescript
function maxFruits(fruits: number[][]): number {
  const n = fruits.length;
  // Sum of main diagonal — child from (0,0) must take the main diagonal
  let diagSum = 0;
  for (let i = 0; i < n; i++) diagSum += fruits[i][i];

  // DP that computes the maximum path-sum for the child starting at (0, n-1)
  // and moving downwards while staying on/above the main diagonal (j >= i).
  // It returns the best sum including the final cell (n-1, n-1).
  function triangleMax(mat: number[][]): number {
    const NEG = Number.MIN_SAFE_INTEGER / 4;
    let dp = new Array<number>(n).fill(NEG);
    dp[n - 1] = mat[0][n - 1];

    for (let i = 1; i < n; i++) {
      const ndp = new Array<number>(n).fill(NEG);
      // only columns j >= i are valid to stay above (or on) main diagonal
      for (let j = i; j < n; j++) {
        let best = dp[j]; // from (i-1, j)
        if (j + 1 < n) best = Math.max(best, dp[j + 1]); // from (i-1, j+1)
        if (j - 1 >= i - 1) best = Math.max(best, dp[j - 1]); // from (i-1, j-1)
        if (best > NEG) ndp[j] = best + mat[i][j];
      }
      dp = ndp;
    }

    return dp[n - 1];
  }

  function transpose(mat: number[][]): number[][] {
    const t = Array.from({ length: n }, () => new Array<number>(n));
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) t[j][i] = mat[i][j];
    }
    return t;
  }

  // Each triangleMax includes the final cell (n-1,n-1). That final cell is
  // already accounted for in diagSum, so subtract it once from each triangle result.
  const upper = triangleMax(fruits) - fruits[n - 1][n - 1];
  const lower = triangleMax(transpose(fruits)) - fruits[n - 1][n - 1];

  return diagSum + upper + lower;
}

// Example usage:
// const fruits = [[1,2,3,4],[5,6,8,7],[9,10,11,12],[13,14,15,16]];
// console.log(maxFruits(fruits)); // 100
```

Sweep j from x to n-1 while maintaining a balanced ordered set (treap) of nums[i] for i <= j-x; for each nums[j] query its predecessor and successor in the set and update the minimum difference.

```typescript
class TreapNode {
  key: number;
  pr: number;
  left: TreapNode | null = null;
  right: TreapNode | null = null;
  cnt: number = 1; // allow duplicates
  constructor(key: number) {
    this.key = key;
    this.pr = Math.random();
  }
}

class Treap {
  private root: TreapNode | null = null;

  private rotateRight(y: TreapNode): TreapNode {
    const x = y.left!;
    y.left = x.right;
    x.right = y;
    return x;
  }

  private rotateLeft(x: TreapNode): TreapNode {
    const y = x.right!;
    x.right = y.left;
    y.left = x;
    return y;
  }

  insert(val: number): void {
    this.root = this._insert(this.root, val);
  }

  private _insert(node: TreapNode | null, val: number): TreapNode {
    if (node === null) return new TreapNode(val);
    if (val === node.key) {
      node.cnt++;
      return node;
    }
    if (val < node.key) {
      node.left = this._insert(node.left, val);
      if (node.left!.pr < node.pr) node = this.rotateRight(node);
    } else {
      node.right = this._insert(node.right, val);
      if (node.right!.pr < node.pr) node = this.rotateLeft(node);
    }
    return node;
  }

  // largest key <= target, or null if none
  predecessor(target: number): number | null {
    let cur = this.root;
    let ans: number | null = null;
    while (cur) {
      if (cur.key <= target) {
        ans = cur.key;
        cur = cur.right;
      } else {
        cur = cur.left;
      }
    }
    return ans;
  }

  // smallest key >= target, or null if none
  successor(target: number): number | null {
    let cur = this.root;
    let ans: number | null = null;
    while (cur) {
      if (cur.key >= target) {
        ans = cur.key;
        cur = cur.left;
      } else {
        cur = cur.right;
      }
    }
    return ans;
  }
}

function minAbsoluteDifferenceWithConstraint(nums: number[], x: number): number {
  const n = nums.length;
  if (n === 0) return 0;
  // If x == 0, picking same index is allowed and gives 0
  if (x === 0) return 0;

  const set = new Treap();
  let ans = Number.POSITIVE_INFINITY;

  // For each j from x..n-1, insert nums[j-x] (index i = j-x becomes available)
  for (let j = x; j < n; ++j) {
    set.insert(nums[j - x]);
    const v = nums[j];
    const low = set.predecessor(v);
    if (low !== null) ans = Math.min(ans, Math.abs(v - low));
    const high = set.successor(v);
    if (high !== null) ans = Math.min(ans, Math.abs(v - high));
    if (ans === 0) return 0; // early exit
  }

  return ans === Number.POSITIVE_INFINITY ? 0 : ans;
}

// Example usage:
// console.log(minAbsoluteDifferenceWithConstraint([4,3,2,4], 2)); // 0

```

Build a map from stop -> list of route indices and run a multi-source BFS over routes (treating routes as nodes); each BFS level adds one bus ride and you return the level when any visited route contains the target.

```typescript
function numBusesToDestination(routes: number[][], source: number, target: number): number {
  if (source === target) return 0;

  // map stop -> list of route indices that include that stop
  const stopToRoutes = new Map<number, number[]>();
  for (let i = 0; i < routes.length; i++) {
    for (const stop of routes[i]) {
      if (!stopToRoutes.has(stop)) stopToRoutes.set(stop, []);
      stopToRoutes.get(stop)!.push(i);
    }
  }

  const visited = new Array<boolean>(routes.length).fill(false);
  const queue: number[] = []; // queue of route indices

  // initialize multi-source BFS with all routes that contain 'source'
  if (!stopToRoutes.has(source)) return -1;
  for (const r of stopToRoutes.get(source)!) {
    visited[r] = true;
    queue.push(r);
  }

  let buses = 1; // number of buses taken so far (we've boarded the initial routes)
  let head = 0; // index for queue head to avoid O(n) shifts

  while (head < queue.length) {
    const levelSize = queue.length - head;
    for (let i = 0; i < levelSize; i++) {
      const routeIdx = queue[head++];
      // check every stop in this route
      for (const stop of routes[routeIdx]) {
        if (stop === target) return buses;
        const nextRoutes = stopToRoutes.get(stop);
        if (!nextRoutes) continue;
        for (const nr of nextRoutes) {
          if (!visited[nr]) {
            visited[nr] = true;
            queue.push(nr);
          }
        }
      }
    }
    buses++;
  }

  return -1;
}

// Example usage
console.log(numBusesToDestination([[1,2,7],[3,6,7]], 1, 6)); // 2
