For each right endpoint, enumerate the number of zeros in the substring up to O(sqrt(n)); for each zero-count compute how many left endpoints produce enough ones and sum the valid left choices (also count all-ones substrings separately).

```typescript
function countDominantSubstrings(s: string): number {
  const n = s.length;
  // positions of zeros with a sentinel 0 at index 0
  const zeroPos: number[] = [0];
  for (let i = 1; i <= n; i++) {
    if (s[i - 1] === '0') zeroPos.push(i);
  }

  // upperBound helper: first index with arr[idx] > target
  const upperBound = (arr: number[], target: number) => {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (arr[mid] <= target) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };

  const maxZero = Math.floor(Math.sqrt(n));
  let ans = 0;
  let onesRun = 0; // length of consecutive ones ending at current right

  for (let r = 1; r <= n; r++) {
    // count substrings with 0 zeros (all-ones substrings ending at r)
    if (s[r - 1] === '1') onesRun++; else onesRun = 0;
    ans += onesRun;

    // index of last zero position <= r in zeroPos
    const idx = upperBound(zeroPos, r) - 1;
    // enumerate number of zeros in substring
    for (let cnt0 = 1; cnt0 <= maxZero && idx - cnt0 + 1 >= 1; cnt0++) {
      const jIndex = idx - cnt0 + 1; // index in zeroPos of the leftmost zero inside substring
      const j = zeroPos[jIndex];
      const pre = zeroPos[jIndex - 1]; // position of previous zero before j (sentinel 0 if none)
      const cnt1 = r - pre - cnt0; // maximum ones available for substrings ending at r with these zeros
      const need = cnt0 * cnt0;
      if (cnt1 < need) continue; // not enough ones for any left boundary with this cnt0

      const leftChoicesFromZeros = j - pre; // possible left starts that include exactly cnt0 zeros
      const leftChoicesFromOnes = cnt1 - need + 1;
      ans += Math.min(leftChoicesFromZeros, leftChoicesFromOnes);
    }
  }

  return ans;
}

// Example usage:
console.log(countDominantSubstrings("00011")); // 5
console.log(countDominantSubstrings("101101")); // 16
