Keep two heaps — a max-heap for the lower half and a min-heap for the upper half — insert into the max-heap, move the top to the min-heap and rebalance so the max-heap has at most one extra element; the median is then available from the heap tops.

```typescript
class Heap {
  private data: number[] = [];
  private cmp: (a: number, b: number) => boolean;

  constructor(cmp: (a: number, b: number) => boolean) {
    this.cmp = cmp;
  }

  size(): number { return this.data.length; }
  peek(): number { return this.data[0]; }

  push(val: number): void {
    this.data.push(val);
    this.siftUp(this.data.length - 1);
  }

  pop(): number {
    const top = this.data[0];
    const last = this.data.pop()!;
    if (this.data.length > 0) {
      this.data[0] = last;
      this.siftDown(0);
    }
    return top;
  }

  private siftUp(i: number): void {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.cmp(this.data[i], this.data[p])) {
        [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
        i = p;
      } else break;
    }
  }

  private siftDown(i: number): void {
    const n = this.data.length;
    while (true) {
      let best = i;
      const l = 2 * i + 1;
      const r = l + 1;
      if (l < n && this.cmp(this.data[l], this.data[best])) best = l;
      if (r < n && this.cmp(this.data[r], this.data[best])) best = r;
      if (best === i) break;
      [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
      i = best;
    }
  }
}

class MedianFinder {
  private lo: Heap; // max-heap
  private hi: Heap; // min-heap

  constructor() {
    this.lo = new Heap((a, b) => a > b);
    this.hi = new Heap((a, b) => a < b);
  }

  addNum(num: number): void {
    // Step 1: always push to lo
    this.lo.push(num);
    // Step 2: move the largest from lo to hi
    this.hi.push(this.lo.pop());
    // Step 3: if hi has more elements, move its smallest back to lo
    if (this.hi.size() > this.lo.size()) {
      this.lo.push(this.hi.pop());
    }
  }

  findMedian(): number {
    if (this.lo.size() > this.hi.size()) return this.lo.peek();
    return (this.lo.peek() + this.hi.peek()) / 2;
  }
}

// Example usage:
// const mf = new MedianFinder();
// mf.addNum(1); mf.addNum(2); console.log(mf.findMedian()); // 1.5
// mf.addNum(3); console.log(mf.findMedian()); // 2.0
```

Normalize pairs as (a<b), for each left index L maintain the smallest and second-smallest right endpoints b among pairs with left endpoint >= L (by scanning L from n down to 1); the base valid subarrays come from the smallest b, and for each L the smallest-pair gets credited with (secondSmallest - smallest) extra subarrays it uniquely blocks — pick the pair with maximum credited amount to remove.

```typescript
function maxSubarrays(n: number, conflictingPairs: number[][]): number {
  const m = conflictingPairs.length;
  // Normalize pairs so a < b and group by left endpoint a
  const perA: { b: number; id: number }[][] = Array.from({ length: n + 1 }, () => []);
  for (let i = 0; i < m; ++i) {
    let a = conflictingPairs[i][0];
    let b = conflictingPairs[i][1];
    if (a > b) [a, b] = [b, a];
    perA[a].push({ b, id: i });
  }

  const INF = n + 1;
  const unique = new Array<number>(m).fill(0);

  let b1 = INF; // smallest b in current multiset
  let id1 = -1;  // id of the pair providing b1
  let b2 = INF; // second smallest b

  let baseValid = 0;

  // iterate L from n down to 1, inserting pairs with left endpoint == L
  for (let L = n; L >= 1; --L) {
    for (const p of perA[L]) {
      const b = p.b;
      const id = p.id;
      if (b < b1) {
        // shift current smallest to second
        b2 = b1;
        b1 = b;
        id1 = id;
      } else if (b < b2) {
        b2 = b;
      }
    }

    if (b1 === INF) {
      // no conflict for left L
      baseValid += (n - L + 1);
    } else {
      // valid right endpoints are [L .. b1-1]
      baseValid += (b1 - L);
      // contribution to the pair that is currently the earliest conflict
      const nextB = (b2 === INF ? INF : b2);
      const contrib = (nextB === INF ? (n + 1) : nextB) - b1;
      // if contrib could be 0 (ties or no room) it adds nothing
      if (contrib > 0 && id1 >= 0) unique[id1] += contrib;
    }
  }

  // best single-pair removal is to remove the pair with maximum unique contribution
  let maxUnique = 0;
  for (let i = 0; i < m; ++i) if (unique[i] > maxUnique) maxUnique = unique[i];

  return baseValid + maxUnique;
}

