Count total letter frequencies and number of words with odd length; if the number of letters with odd total frequency <= number of odd-length words then all strings can be palindromes, otherwise every two extra odd-frequency letters beyond that reduce the count of achievable palindromes by one.

```typescript
function maxPalindromes(words: string[]): number {
  const freq = new Array<number>(26).fill(0);
  let oddLengthWords = 0;

  // accumulate global letter frequencies and count odd-length words
  for (const w of words) {
    if (w.length % 2 === 1) oddLengthWords++;
    for (let i = 0; i < w.length; i++) {
      freq[w.charCodeAt(i) - 97]++;
    }
  }

  // count letters that have odd total frequency
  let oddLetterCount = 0;
  for (let f of freq) if (f % 2 === 1) oddLetterCount++;

  const n = words.length;
  if (oddLetterCount <= oddLengthWords) return n;
  // each pair of extra odd letters (beyond available odd-length centers) forces losing one palindrome
  const extra = oddLetterCount - oddLengthWords;
  return n - Math.floor(extra / 2);
}

// Example usage:
// console.log(maxPalindromes(["abbb","ba","aa"])); // 3
```
